window.RV=[{"d":"2026-11","a":"Алексей","t":"Спасибо Ивану за отличный автомобиль","x":"Спасибо Ивану за отличный автомобиль","m":"","th":[],"img":"r000_0","bo":0},{"d":"2026-10","a":"Alex","t":"Заказывал BMW 318 проходящий по утилизационному сбору, санкционный автомобиль ждали 2 месяца, до этого был Мерседес с класс, разница колоссальная очень приятный автомобиль. Машина прибыла в идеальном состоянии с пробегом 20.000.Платил всё сам через банк, никаких проблем. Отработали на 100% никаких подвохов и по цене точно как договаривались. Рекомендую заказывать.","x":"Заказывал BMW 318 проходящий по утилизационному сбору, санкционный автомобиль ждали 2 месяца, до этого был Мерседес с класс, разница колоссальная очень приятный автомобиль.","m":"BMW","th":["price"],"img":"r001_0","bo":0},{"d":"2026-10","a":"Нина","t":"Спасибо Ивану Сергею за отличное авто за хорошо проделанную работу","x":"Спасибо Ивану Сергею за отличное авто за хорошо проделанную работу","m":"","th":[],"img":"r002_0","bo":1},{"d":"2026-10","a":"Лолита","t":"Это был мой первый опыт покупки авто из Японии, поэтому боялась ошибиться или столкнуться с недобросовестными продавцами. В этой компании сразу почувствовала себя уверенно: менеджер Сергей терпеливо отвечал на все вопросы, даже самые простые, и не торопил с решением. Помогли выбрать вариант, который реально подходит по бюджету и параметрам, а дальше полностью сопровождали процесс. На каждом шаге присылали отчёт и статус, так что не было ощущения «машина где-то едет, и никто не знает где». В итоге машина пришла в отличном состоянии, полностью соответствует описанию. Спасибо за честность и заботу о клиенте — буду рекомендовать вас знакомым!","x":"Это был мой первый опыт покупки авто из Японии, поэтому боялась ошибиться или столкнуться с недобросовестными продавцами.","m":"","th":["touch","report","first"],"img":"r003_0","bo":1},{"d":"2026-10","a":"Валентина","t":"Всем здравствуйте! Хотим рассказать о нашем опыте сотрудничества с Сергеем и Олегом. Заказали машину Хонда Фрид 2021 в красивом цвете. Мы люди в возрасте, поэтому ко всему относились с опаской. Процесс был несложным Сергей на каждом этапе помогал, даже где то привезти увезти оформить документы. Очень рады что повстречали таких специалистов в своем деле. Покупкой довольны, в следующий раз обязательно обратимся сюда!","x":"Хотим рассказать о нашем опыте сотрудничества с Сергеем и Олегом.","m":"Honda Freed","th":["docs"],"img":"r004_0","bo":1},{"d":"2026-10","a":"Алёна","t":"Привезли авто из Японии ровно за месяц — сроки соблюдены без задержек. Машина в отличном состоянии, полностью соответствует описанию. Важнее всего для нас была прозрачность: нам показывали аукционный лист, присылали фото и отчёты, поэтому мы всегда понимали, на каком этапе находится заказ.\nОтдельно отметим реальную помощь с оформлением — ничего не пришлось делать самим, всё подробно объяснили и подсказали.\nЗдесь цены «под ключ»!\nОднозначно рекомендуем!\nБлагодарим Вас за качественную и добросовестную работу","x":"Важнее всего для нас была прозрачность: нам показывали аукционный лист, присылали фото и отчёты, поэтому мы всегда понимали, на каком этапе находится заказ.","m":"","th":["price","term","report","docs"],"img":"r005_0","bo":0},{"d":"2026-10","a":"Екатерина","t":"Огромная благодарность компании Автозаказ28.\nОстались в восторге. Авто превзошло все наши ожидания. Вы профессионалы своего дела. На связи были 24/7, отвечали на все интересующие вопросы.\nТеперь будем обращаться только к\nВам. Успехов Вам и процветания Вашей компании","x":"На связи были 24/7, отвечали на все интересующие вопросы.","m":"","th":["touch"],"img":"r006_0","bo":1},{"d":"2026-10","a":"Александр","t":"Друзья, хочу оставить отзыв для Олега и Сергея. Если вы ищете, кому доверить покупку машины в Японии — вам к ним. Мы с супругой искали надежный вариант, и ребята превзошли все ожидания. Ни дня задержки, постоянная связь, фотоотчеты. В итоге машина (Toyota Sienta 2022 года) приехала в Амурскую область в целости и сохранности, без единой царапины. Всё честно, открыто и по договору. Огромная благодарность за ваш труд и человеческое отношение!","x":"Ни дня задержки, постоянная связь, фотоотчеты.","m":"Toyota Sienta","th":["report"],"img":"r007_0","bo":1},{"d":"2026-10","a":"Сергей","t":"Обратился за помощью в покупке автомобиля, купил БМВ с аукциона. Процесс покупки был прост, на каждом этапе давали инструкции, пришла за один месяц. Покупкой доволен. Бюджет был 800.000 рублей, уложились. Спасибо Сергею, Олегу, Ивану за проделанную работу!","x":"Обратился за помощью в покупке автомобиля, купил БМВ с аукциона.","m":"BMW","th":["price","term"],"img":"r008_0","bo":0},{"d":"2026-10","a":"Ирина","t":"Покупка автомобиля — всегда волнительное событие, а когда речь идёт о заказе из другой страны, волнение и вовсе удваивается. Именно поэтому так ценно встретить настоящих профессионалов, которые помогают пройти этот путь спокойно и уверенно.\nОт всей души благодарю компанию «Автозаказ28» и лично Сергея за безупречную работу! Уже с первой встречи я почувствовала, что нахожусь в надёжных руках. Сергей терпеливо и подробно разъяснил все этапы покупки, не торопил с решением и помог подобрать автомобиль именно под мои потребности. Особенно ценю, что он регулярно присылал фото машины ещё до отправки — это снимало тревожность и давало ощущение полного контроля над процессом.\nАвтомобиль прибыл точно в оговорённые сроки, в идеальном состоянии, с полным комплектом документов.\nСпасибо за вашу заботу и высокий профессионализм! С радостью порекомендую «Автозаказ28» своим друзьям и знакомым.","x":"Уже с первой встречи я почувствовала, что нахожусь в надёжных руках.","m":"","th":["term","report","docs"],"img":"r009_0","bo":0},{"d":"2026-09","a":"Анатолий","t":"В Автозаказе 28 приобрели автомобиль jimny Sierra, 4,5 балла при заключении договора автомобиль из Японии был привезён за 21 день на автовозе, в идеальном состоянии, спасибо Сергею за помощь в оформлении документов за оперативность и порядочность, был приятно удивлен, рекомендую.","x":"В Автозаказе 28 приобрели автомобиль jimny Sierra, 4,5 балла при заключении договора автомобиль из Японии был привезён за 21 день на автовозе, в идеальном состоянии, спасибо Сергею за…","m":"Suzuki Jimny","th":["term","docs"],"img":"r010_0","bo":0},{"d":"2026-09","a":"Ирина","t":"Хочу выразить огромную благодарность за помощь в покупке автомобиля. С самого начала сопровождали на каждом этапе, всегда были на связи и отвечали на все вопросы, очень приятно, когда у клиенту такое отношение. Спасибо за отличный автомобиль и проффесионалтный подход. Все прошло максимально комфортно и спокойно. Остались только положительные эмоции от покупки.","x":"С самого начала сопровождали на каждом этапе, всегда были на связи и отвечали на все вопросы, очень приятно, когда у клиенту такое отношение.","m":"","th":["touch"],"img":"r011_0","bo":0},{"d":"2026-09","a":"Юлия","t":"Я хочу огромное спасибо сказать Олегу и Сергею за привезенный авмобиль тойота C-Hr. Вы просто лучшие. И я благодарна судьбе что встретила именно вас. Хочу вам пожелать побольше клентов. И буду я всем советовать что бы обращались к вам. Низкий вам поклон за такую ответственную работу. С уважением Юлия и Алексей.","x":"Я хочу огромное спасибо сказать Олегу и Сергею за привезенный авмобиль тойота C-Hr.","m":"Toyota C-HR","th":[],"img":"","bo":0},{"d":"2026-09","a":"Сергей","t":"Заказали машину из Японии, машину ждали один месяц. Пришла на автовозе, забирали чистую машину с полным пакетом документов. По сумме сколько договорились, так и получилось, заключали договор. Покупкой довольны, когда забирали, два Джимни стояли, наш который стандартный. Если нужен автомобиль, будем также заказывать здесь, спасибо!","x":"По сумме сколько договорились, так и получилось, заключали договор.","m":"Suzuki Jimny","th":["price","term","docs"],"img":"r013_0","bo":0},{"d":"2026-09","a":"Игорь","t":"Всем здравствуйте! Заказал машину Сиенту в этой компании, прилетел из Москвы до Владивостока за машиной. Договорились о явке на таможню чтобы ускорить выпуск, и на следующей день уже забрал машину. Договор все условия выполнены на 100%.Претензий к работе нет. Проездом заехал ещё в Благовещенск, на месте масло поменяли, фары отполировали, локально вмятины устранили, все быстро и отлаженно. В компании свое дело знают точно. Спасибо большое. Рекомендую обращаться.","x":"Договорились о явке на таможню чтобы ускорить выпуск, и на следующей день уже забрал машину.","m":"Toyota Sienta","th":[],"img":"r014_0","bo":1},{"d":"2026-09","a":"Светлана","t":"Заказали авто Toyota Yaris 2023 года в комплектации G, «под ключ» С ПРОБЕГОМ 1700 км, да да это не опечатка 1700 км\nБарабанная дробь …. Цена 1 50 тысяч РУБЛЕЙ\nХочу выразить огромнейшую благодарность специалисту Сергею\nСергей большой молодец, во-первых хочется сказать про отношение к клиентам, очень внимательный парень всегда на связи\nГде-то даже просто с экономить копеечку\nПРОСТО МОЛОДЕЦ, нечего сказать\nВсе честно, все на совесть\nПомог со всеми документами от оформления договора, да записи в ГАИ\nЕсли за авто, ТО ТОЛЬКО СЮДА\nМиллион раз спасибо за это сотрудничество","x":"Сергей большой молодец, во-первых хочется сказать про отношение к клиентам, очень внимательный парень всегда на связи","m":"Toyota Yaris","th":["price","touch","docs"],"img":"r015_0","bo":0},{"d":"2026-08","a":"Дмитрий","t":"Встретили, проводили, все хорошо","x":"Встретили, проводили, все хорошо","m":"","th":[],"img":"r016_0","bo":0},{"d":"2026-08","a":"Клиент","t":"В очередной раз спасибо Сергею, машина куплена в очень хорошем состоянии, ребята молодцы работают быстро, и качественно.","x":"В очередной раз спасибо Сергею, машина куплена в очень хорошем состоянии, ребята молодцы работают быстро, и качественно.","m":"","th":["again"],"img":"r017_0","bo":0},{"d":"2026-08","a":"Алексей","t":"По рекомендации обратился в данную организацию. Ездил на тойота виш, хотел новую машину, сделали trade-in под заказ на харриер, заключили договор. Сразу сказали придётся ждать, шла примерно 3 месяца до Благовещенска. Машина пришла, всё устроило, претензий нет. В следующий раз обращусь в эту же компанию для заказа или обмена авто. Спасибо.","x":"Ездил на тойота виш, хотел новую машину, сделали trade-in под заказ на харриер, заключили договор.","m":"Toyota Harrier","th":["friend","trade"],"img":"r018_0","bo":1},{"d":"2026-08","a":"Виктор","t":"Не первый раз заказываем автомобиль в этой компании Покупка и доставка заняла 2 месяца, бюджет был ограниченный, заняло время, покупкой довольны Фрид в комплектации модуло. Рекомендуем! Спасибо Сергею и Олегу!","x":"Не первый раз заказываем автомобиль в этой компании Покупка и доставка заняла 2 месяца, бюджет был ограниченный, заняло время, покупкой довольны Фрид в комплектации модуло.","m":"Honda Freed","th":["again"],"img":"r019_0","bo":0},{"d":"2026-07","a":"Лилия","t":"Работаем с Сергеем не первый раз. Машину нашли и доставили быстро. За свою цену машинка просто Рекомендую","x":"Работаем с Сергеем не первый раз.","m":"","th":["term","again"],"img":"","bo":0},{"d":"2026-07","a":"Марина","t":"Выражаю огромную благодарность «Автозаказ28» за безупречное приобретение автомобиля из Японии! Нашла компанию по отзывам и не прогадала: ребята — настоящие профессионалы. Ответственные, честные, все вопросы решают молниеносно. Полное отсутствие скрытых проблем с машиной и прозрачность на каждом этапе сделки. Смело рекомендую, если вам нужен результат без лишней головной боли!","x":"Полное отсутствие скрытых проблем с машиной и прозрачность на каждом этапе сделки.","m":"","th":["price"],"img":"r021_0","bo":0},{"d":"2026-07","a":"Сергей","t":"Не первую машину заказываем в этой компании. Купили джимни 2023 года с пробегом 9.000, искали сразу укомплектованный, привезли за 1.5 месяца, машина непроходная была 14 дней стояла без дела. Покупкой довольны, состояние новой машины. Все процессы понятны, на все вопросы быстро получали ответ. Рекомендуем компанию для заказа авто.","x":"Не первую машину заказываем в этой компании.","m":"Suzuki Jimny","th":["touch","again"],"img":"r022_0","bo":0},{"d":"2026-06","a":"Лана","t":"Огромное спасибо команде Автозаказ28! Заказывали машину с доставкой в Благовещенск. Все прошло просто идеально: привезли ровно в оговоренный срок, без задержек и форс-мажоров. Машина оказалась в идеальном состоянии — чистая, технически исправная, выглядит даже лучше, чем на фото. Отдельное спасибо Сергею за оперативную связь. Очень приятно иметь дело с профессионалами. Теперь только к вам!","x":"Машина оказалась в идеальном состоянии — чистая, технически исправная, выглядит даже лучше, чем на фото.","m":"","th":["term"],"img":"r023_0","bo":1},{"d":"2026-06","a":"Ирина","t":"Впервые заказывали авто с аукциона для дочери. Переживали, что процесс сложный и долгий, но опасения не оправдались. Спасибо огромное Сергею — настоящий профессионал и фанат своего дела! Он буквально «разжевал» все этапы, помог выбрать нужный нам автомобиль под наш бюджет, постоянно держал в курсе событий, всегда был на связи, даже когда возникали мелкие вопросы уже после покупки. Немного терпения и автомобиль приехал «под ключ» в идеальном состоянии: сел и поехал, никаких сюрпризов. Самое приятное — уложились даже меньше запланированной суммы, что нас очень порадовало. Рекомендую всем данную компанию! Обращайтесь не раздумывая!","x":"Впервые заказывали авто с аукциона для дочери.","m":"","th":["price","touch","first"],"img":"r024_0","bo":1},{"d":"2026-06","a":"Дарья","t":"Заказала авто из Японии через вашу компанию - все прошло чётко! Специалист Сергей все подробно объяснил, стоимость «под ключ» не изменилась, машину доставили в срок и в идеальном состоянии. Спасибо за прозрачность и профессионализм - рекомендую!","x":"Специалист Сергей все подробно объяснил, стоимость «под ключ» не изменилась, машину доставили в срок и в идеальном состоянии.","m":"","th":["price","term"],"img":"r025_0","bo":0},{"d":"2026-06","a":"Екатерина","t":"Всем добрый день! Хочется выразить огромную благодарность компании \" Автозаказ 28\"… По рекомендации знакомых обратилась к Сергею по вопросу приобретения первого автомобиля... Мы обговорили все нюансы ( марка, цвет, год, комплектация, пробег, примерная стоимость…). И не прошло и пару дней, как на продаже аукциона появился просто идеальный вариант, с минимальным пробегом в 25000, идеальная комплектация и цена оказалась в разы меньше, чем мы расчитывали… с Сергеем связь поддерживали 24/7, всю информацию получали оперативно. С его стороны была огромная поддержка, чёткие инструкции... Нам всегда присылали фотографии и информировали о том, на каком этапе все происходит! В итоге с момента обращения прошло 3 недели, как мы получили Нашу красавицу... Машина пришла в идеальном состоянии… Просто \" сел и поехал\"!… Эмоции переполняют! От всего сердца хочется ещё раз сказать, ОГРОМНОЕ СПАСИБО\" Автозаказу 28\", лично Сергею за БЕЗУПРЕЧНУЮ работу! С уверенностью буду рекомендовать вашу надёжную компанию... От души желаю Вам дальнейшего процветания и адекватных клиентов… Вы УМНИЧКИ с БОЛЬШОЙ буквы…","x":"И не прошло и пару дней, как на продаже аукциона появился просто идеальный вариант, с минимальным пробегом в 25000, идеальная комплектация и цена оказалась в разы меньше, чем мы расчитывали…","m":"","th":["touch","term","report","first","friend"],"img":"r026_0","bo":1},{"d":"2026-06","a":"Владимир","t":"Хотел поделиться своим положительным впечатлением. Покупаю не первую машину в этой фирме. Самое главное что всё официально, договор, оформление через Госуслуги. Машину подобрали быстро под мои параметры. Машина уже приехала, сам забирал, всё отлично, машина огонь, советую обращаться в эту фирму.","x":"Самое главное что всё официально, договор, оформление через Госуслуги.","m":"","th":["docs","again"],"img":"r027_0","bo":0},{"d":"2026-06","a":"Татьяна","t":"Купили машину в компании \"Автозаказ 28\". Механизм покупки отлажен безупречно. Предварительно с Сергеем были оговорены модель, цвет, пробег машины, примерная цена. Как только появился в продаже на аукционе нужный вариант, Сергей его приобрёл. Действовали строго в соответствии с инструкциями, которые давал Сергей. Общались через мессенджер.\nВсю информацию получали оперативно. На возникающие вопросы всегда получали быстрый ответ.\nСергей постоянно сообщал, что и как происходит, где находится машина, когда прибудет во Владивосток, потом в Благовещенск. Присылал фотографии авто, которые позволяли оценить состояние машины до отправки из Японии и по прибытии во Владивосток.\nПокупкой остались очень довольны, и можем с уверенностью рекомендовать данную компанию как абсолютно надёжную и профессионально работающую.\nНикаких лишних сборов. Все прозрачно и понятно: что, где, как и сколько платить (и за что именно).\nСпасибо Сергею за безупречную работу!","x":"Предварительно с Сергеем были оговорены модель, цвет, пробег машины, примерная цена.","m":"","th":["price","report"],"img":"r028_0","bo":1},{"d":"2026-06","a":"Анна","t":"Спасибо Автозаказ 28 в лице менеджера Сергея за отличную работу, начиная с консультации по выбору подходящего авто и заканчивая его доставкой до подъезда. Услуга оказана качественно, сопровождение на каждом этапе. Сергей максимально старается в своей работе, чтобы клиент полностью остался доволен покупкой. Ещё раз спасибо! Рекомендую данную компанию!","x":"Услуга оказана качественно, сопровождение на каждом этапе.","m":"","th":[],"img":"r029_0","bo":1},{"d":"2026-06","a":"Вячеслав","t":"Обратились за покупкой санкционной машины Тойоты Харриер, была машина приехали поговорили насчёт обмена, договорились. Ждали новую машину 3 месяца, в договоре фиксировали все суммы нашей и новой машины. Всё было исполнено согласно нашему договору. Результат идеальный, мы довольны, работа Сергея и Олега понравилась, на все вопросы сразу получали ответы, машина пришла на автовозе, забрали чистую. Вообщем рекомендуем к сотрудничеству, всё отлично.","x":"Обратились за покупкой санкционной машины Тойоты Харриер, была машина приехали поговорили насчёт обмена, договорились.","m":"Toyota Harrier","th":["price","touch","trade"],"img":"r030_0","bo":0},{"d":"2026-06","a":"Руслан","t":"Заказывали автомобиль в компании «Автозаказ28» и остались очень довольны результатом! Главные плюсы — честность и прозрачность: никаких скрытых комиссий или навязывания ненужных услуг.\nОтдельная благодарность менеджеру Сергею. Он искренне заинтересован в том, чтобы подобрать именно ту машину, которую вы ищете, и по самой выгодной цене. Сергей всегда на связи и оперативно решает любые возникающие вопросы. Рекомендую!","x":"Главные плюсы — честность и прозрачность: никаких скрытых комиссий или навязывания ненужных услуг.","m":"","th":["price","touch"],"img":"r031_0","bo":0},{"d":"2026-05","a":"Анна","t":"Обращаемся к Сергею не первый раз, делает всё в лучшем виде\nВсе пожелания выполнены!\nБлагодарны за выполненную работу, в будущем будем обращаться к вам!","x":"Обращаемся к Сергею не первый раз, делает всё в лучшем виде","m":"","th":["again"],"img":"r032_0","bo":1},{"d":"2026-05","a":"Алексей","t":"Огромная благодарность и спасибо Сергею! Обратился к нему по рекомендации и не пожалел! Заключили договор и пошла работа 24/7, постоянно на связи, рекомендации, советы! Машину купил в отличном состоянии. Всё под ключ - покупка машины и доставка автовозом до Волгограда! Всё честно, ответственно, достойно!","x":"Заключили договор и пошла работа 24/7, постоянно на связи, рекомендации, советы!","m":"","th":["price","touch","friend"],"img":"r033_0","bo":0},{"d":"2026-05","a":"Клиент","t":"Благодарим Сергея и Олега за помощь в покупке авто. Санкционный авто, пришёл не быстро зато без накладок.","x":"Санкционный авто, пришёл не быстро зато без накладок.","m":"","th":[],"img":"r034_0","bo":0},{"d":"2026-04","a":"Клиент","t":"Хочу выразить огромную благодарность Олегу и Сергею.\nВсегда боялся связываться с заказом авто из-за границы: думал, что это вечные нервы, задержки и внезапные комиссии.\nНо решился и не прогадал.\nЗаказал Харька. Компания Автозаказ28 сделала всё \"под ключ\": от поиска лота на аукционе до того, как я сел в машину. Машину выдали чистую, все на месте проверили, подтверждение пробега и состояния, документы оформили быстро. Я просто ждал и получал удовольствие от процесса.\nСпасибо за сервис! Теперь только к вам.","x":"Всегда боялся связываться с заказом авто из-за границы: думал, что это вечные нервы, задержки и внезапные комиссии.","m":"Toyota Harrier","th":["price","docs"],"img":"","bo":0},{"d":"2026-04","a":"Юлия","t":"Впервые решили приобрести машину под заказ, соответсвенно опыта ноль. Обратились по рекомендации и не прогадали Поддержка 24/7 Реально сошлись звезды! Машина исключительно по заявленным нами характеристикам! теперь радует глаз Новосибирцев еще раз благодарим и теперь всегда только к вам! С вами нам не страшно","x":"Впервые решили приобрести машину под заказ, соответсвенно опыта ноль.","m":"","th":["touch","first","friend"],"img":"r036_0","bo":0},{"d":"2026-04","a":"Серж","t":"Доброго дня. Неделю назад приобрел себе отличный автомобиль из Японии через Автозаказ28. Остался доволен и машиной и подходом к делу. А главное что ребята от начала и до конца с тобой. Увидел, проплатил, забрал ключи и уехал. Всем рекомендую эту компанию, а Олегу и Сергею удачи в бизнесе.","x":"Неделю назад приобрел себе отличный автомобиль из Японии через Автозаказ28.","m":"","th":[],"img":"r037_0","bo":0},{"d":"2026-04","a":"Вячеслав","t":"Олег и Сергей, огромная вам благодарность от всей души за человечность отзывчивость и порядочность. Я рад что заключил договор именно с вами. От заказа до постановки на учёт прошло менее месяца, поддержка была на всём протяжении сделки очень актуальна и своевременна. Рекомендую фирму Автозаказ28, ответственно подходят к работе.","x":"Я рад что заключил договор именно с вами.","m":"","th":["term","docs"],"img":"r038_0","bo":0},{"d":"2026-04","a":"Виталий","t":"Автомобиль приобретен и доставлен по договору в кратчайшие сроки. Остался доволен работой Сергея и Олега. Они профессионалы своего дела. Рекомендую.","x":"Автомобиль приобретен и доставлен по договору в кратчайшие сроки.","m":"","th":["term"],"img":"r039_0","bo":1},{"d":"2026-04","a":"Александр","t":"Машину привезли в течении месяца, очень понравился подход, большое спасибо Сергею и Олегу за оказанные услуги, вы лучшие","x":"Машину привезли в течении месяца, очень понравился подход, большое спасибо Сергею и Олегу за оказанные услуги, вы лучшие","m":"","th":["term"],"img":"r040_0","bo":1},{"d":"2026-03","a":"Алёна","t":"Купили машинку под работу в компании! Honda n-van маленький компактный и очень вместительный багажник, обратились 15.02.2026 искали 2 недели подходящий вариант, спустя месяц 26.03.2026 машина прибыла в Благовещенск на автовозе, остались очень довольны! Спасибо Сергею и Олегу за проделанную работу, всё быстро без каких либо проблем с оплатами и растаможкой! Побольше довольных клиентов и процветания бизнесу!","x":"Honda n-van маленький компактный и очень вместительный багажник, обратились 15.02.2026 искали 2 недели подходящий вариант, спустя месяц 26.03.2026 машина прибыла в Благовещенск на…","m":"Honda N-Van","th":[],"img":"r041_0","bo":0},{"d":"2026-03","a":"Алексей","t":"Спасибо Сергею, сервис на высшем уровне.\nМашина пришла в отличном состоянии.\nЧистая, с полным баком японского бензина)))","x":"Чистая, с полным баком японского бензина)))","m":"","th":[],"img":"r042_0","bo":1},{"d":"2026-02","a":"Михаил","t":"Хочется сказать огромнейшее спасибо Сергею. Нашёл компанию \"Автозаказ 28\" на дроме, почитал отзывы в 2 ГИС и решил заказать автомобиль именно у них. Выбор пал на Toyota c-hr по адекватной цене, 13.01.26 года заключили договор и 08.02.2026 машина была уже в Благовещенске (А это на минуточку с Японии!). Сегодня забрал, радости нет предела) Рекомендую компанию на все 100%!","x":"Выбор пал на Toyota c-hr по адекватной цене, 13.01.26 года заключили договор и 08.02.2026 машина была уже в Благовещенске (А это на минуточку с Японии!).","m":"Toyota C-HR","th":[],"img":"r043_0","bo":1},{"d":"2026-01","a":"Valentin","t":"Всем привет! Искал на дроме автомобиль, остановился на выборе тайота виш. Обратился к продавцу, пришол в фирму Автозаказ28, познакомился с ребятами, хорошая команда, рассказали, показали, заключили договор. Всё прошло быстро, машина огонь, приехала на автовозе как и договаривались в срок. Спасибо Сергею и Олегу за отличную работу","x":"Обратился к продавцу, пришол в фирму Автозаказ28, познакомился с ребятами, хорошая команда, рассказали, показали, заключили договор.","m":"Toyota Wish","th":["term"],"img":"r044_0","bo":0},{"d":"2026-01","a":"Дарья","t":"По рекомендации знакомого, обратилась к Сергею по вопросу приобретения первого автомобиля. Сергей прислушался к моим пожеланиям, помог выбрать машину. Всегда был на связи, отвечал на все интересующие вопросы. И вот в начале января сбылась моя мечта-машина пришла в указанные сроки, в идеальном состоянии (хотя в связи с праздниками ждала ее позже). Хочу выразить огромную благодарность, за проделанную работу, за ответственный подход абсолютно ко всем моментам. Сергей, СПАСИБО за мою красотку) желаю Вам много заказов и адекватных клиентов)","x":"По рекомендации знакомого, обратилась к Сергею по вопросу приобретения первого автомобиля.","m":"","th":["touch","term","first","friend"],"img":"r045_0","bo":0},{"d":"2026-01","a":"Светлана","t":"Добрый вечер!\nВ эту организацию по покупке автомобиля меня привела рекомендация моей хорошей знакомой, и я осталась очень довольна. Работа была выполнена на высоком профессиональном уровне. Мне помогли подобрать автомобиль.\nНа протяжении всего процесса со мной всегда были на связи и готовы ответить на любые вопросы. Отдельно хочу отметить оперативную и аккуратную доставку автомобиля.\nОгромное спасибо Ивану за его отзывчивость и высокий профессионализм!\nЯ с удовольствием рекомендую эту организацию в покупке автомобиля.","x":"На протяжении всего процесса со мной всегда были на связи и готовы ответить на любые вопросы.","m":"","th":["touch","friend"],"img":"","bo":0},{"d":"2026-01","a":"Клиент","t":"Обратился с покупкой автомобиля тойота аллион 26.11.25, купили быстро 45 тысяч пробег 2009 год и уже 2 декабря оплачивали инвойс в банке, доставили до Владивостока 20 декабря и началась растаможка, успели до нового года. В начале января погрузили на автовоз и машину уже забрал 8 января. На всех этапах быстро отвечали на вопросы, консультировали и помогали. Покупкой доволен как и работой Сергея и Олега, рекомендую к работе с данными людьми! Спасибо!","x":"В начале января погрузили на автовоз и машину уже забрал 8 января.","m":"Toyota Allion","th":["touch"],"img":"r047_0","bo":1},{"d":"2025-12","a":"Елена","t":"Просто хочется сказать Большое спасибо ребятам за автомобиль. Покупали авто таким образом впервые. Хотели HONDA Vezel. У ребят уже был куплен и стоял в Японии. Видимо нас ждал. Очень понравился деловой подход. Ни чего не скрывали, всегда на связи, даже с такими надоедливыми клиентами как мы. Машина огонь. Рекомендуем Всем покупать авто у них.","x":"Ни чего не скрывали, всегда на связи, даже с такими надоедливыми клиентами как мы.","m":"Honda Vezel","th":["touch","first"],"img":"r048_0","bo":0},{"d":"2025-12","a":"Вячеслав","t":"В очередной раз (четвертый раз по счету) заказал автомобиль у Сергея и Олега. На этот раз заказал Toyota Premio 2019 года, в максимальной комплектации, 4,5 балла аукцион, пробег 19 тыс км, цвет снежная королева. Машина новая, огонь! С момента растоможки автомобиль приехал через 10 дней. Все прошло без задержек и нареканий, как и всегда! Авто с автовоза встречал в Благовещенске сам лично. Цены у ребят ниже рыночных, скрытых комиссий нет!\nВсем друзьям и знакомым всегда рекомендую Автозаказ28. Многие уже приобрели авто у ребят.\nХочу поздравить Сергея и Олега с наступающим Новым годом! Желаю процветания, легких и безпроблемных сделок с клиентами!","x":"Цены у ребят ниже рыночных, скрытых комиссий нет!","m":"Toyota Premio","th":["price","term","again"],"img":"r049_0","bo":0},{"d":"2025-12","a":"Виктория","t":"Спасибо огромное Сергею! Заказали машину из Японии, срок доставки по договору стоял до 15 января, машина пришла намного раньше! Ещё Сергей помог поменять резину и антифриз. Машина чистая, всё работает как и было заявлено! Очень доброжелательный, внимательный молодой человек! Ещё и подарочек подарили - японский освежитель воздуха!","x":"Заказали машину из Японии, срок доставки по договору стоял до 15 января, машина пришла намного раньше!","m":"","th":["term"],"img":"r050_0","bo":1},{"d":"2025-12","a":"Андрей","t":"Сегодня мы забрали свой авто. Большое спасибо Сергею. Всё как договаривались, комплектация, цена. Пришлось немного подождать пока появился подходящий вариант. А в остальном всё отлично. Всем рекомендуем заказывать авто у Сергея. Человек внимательный, всегда на связи, учитывает все пожелания клиента.","x":"Всё как договаривались, комплектация, цена.","m":"","th":["price","touch"],"img":"r051_0","bo":1},{"d":"2025-11","a":"Дмитрий","t":"Сергею, большое спасибо за проделанную работу, лучший в своём деле\nВсегда на связи, поможет, подскажет как лучше,\nВыбрал машину на рынке, но встретил Сергея и он порекомендовал, что лучше набраться немного терпения, чтобы мне привезли машину намного лучше и по-моему бюджету (получилось неплохо сэкономить)\nТак и получилось, результат очень сильно оправдал ожидания, это благодаря Сергею. Не было никаких скрытых доплат, сразу честная сумма\nВсем рекомендую,\nЕще раз спасибо за проделанную работу","x":"Всегда на связи, поможет, подскажет как лучше,","m":"","th":["price","touch"],"img":"r052_0","bo":0},{"d":"2025-11","a":"Ирина","t":"Огромное спасибо Сергею за помощь в приобретении авто. Все быстро и качественно. Работали на удалении, прошло все на отлично. Машина просто идеальная, всё как я и хотела. Сергей всегда был на связи, весь путь авто сопровождал фото. Если у кого-то есть сомнения не сомневайтесь, команда Сергея сделает все в лучшем виде. Все расскажут, покажут и посоветуют.","x":"Сергей всегда был на связи, весь путь авто сопровождал фото.","m":"","th":["touch","report"],"img":"r053_0","bo":0},{"d":"2025-11","a":"Марина","t":"Сегодня забрали автомобиль.\nЗаказали у Сергея, очень понравился подход, все подсказал, почему и как.\nВсегда на связи.\nМашину привезли на автовозе, Сергей её получил, нам её подготовил, нам оставалось только сесть и поехать.\nМашинка как новенькая\nСпасибо большое.","x":"Машину привезли на автовозе, Сергей её получил, нам её подготовил, нам оставалось только сесть и поехать.","m":"","th":["touch"],"img":"r054_0","bo":0},{"d":"2025-11","a":"Дарья","t":"Заказывали у Сергея автомобиль Honda Vezel. Покатались год и поняли, что хотим автомобиль лучше. Приняли решение заказать снова у Сергея новый автомобиль Toyota Harrier. Выбор упал на 2021 год белый цвет, максимальной комплектации. Все нюансы были обговорены, оставалось только дождаться свой новый автомобиль с Японии. Сергей доставил авто раньше назначенных сроков и пригнал его сам с Владивостока, не смотря на погодные условия. При этом еще предложил преобрести и комплект зимней резины по ценам ниже Благовещенска, что нас очень порадовало.\nУже второй раз мы остаемся очень довольны работой Автозаказ 28. Все четко, быстро, ясно и без подводных камней. Благодарим Сергея за отлично проделанную работу! Мы очень довольны приобретенным автомобилем - комфорт и надежность. Toyota- управляй мечтой!\nРекомендуем данную компанию!","x":"При этом еще предложил преобрести и комплект зимней резины по ценам ниже Благовещенска, что нас очень порадовало.","m":"Honda Vezel","th":["term","again"],"img":"r055_0","bo":0},{"d":"2025-11","a":"Лидия","t":"Приобрела свой первый долгожданный автомобиль\nОгромное спасибо Сергею и Олегу за то что могли подобрать красивую надёжную экономичную машину Toyota Passo.С минимальным пробегом в идеальном состоянии и по реальной цене.\nВсё прошло без заморочек и все условия договора выполнены безукоризненно.\nОтдельное спасибо Сергею за оперативность ответственность и вежливое отношение к покупателям.\nЕсли надумаете приобрести автомобиль РЕКОМЕНДУЮ обращаться к Сергею и его команде не пожалеете.","x":"Приобрела свой первый долгожданный автомобиль","m":"Toyota Passo","th":["first"],"img":"r056_0","bo":0},{"d":"2025-10","a":"Нурлан","t":"Спасибо огромное, большое, не знаю как выразить словами, честен, пунктуален, старается как для себя, я не даром встретил на своем жизненном пути такого человека, всех благ Вам Сергей","x":"Спасибо огромное, большое, не знаю как выразить словами, честен, пунктуален, старается как для себя, я не даром встретил на своем жизненном пути такого человека, всех благ Вам Сергей","m":"","th":[],"img":"r057_0","bo":1},{"d":"2025-10","a":"Анна","t":"О компании Автозаказ 28 узнали из объявления в Дроме. Были приятно удивлены, какие специалисты там работают. Купили машину Тайота CH-R 2019г. Всё доступно объясняют, помогают на протяжении всего срока сделки. Машину ждали месяц через аукцион в Японии. Пришла в идеальном состоянии. Сергей помог с покупкой билетов на самолёт, с покупкой зимней резины во Владивостоке, переобули машину пока мы летели во Владивосток. По приезду в город помогли с оформлением машины. Ребята молодцы! Уважительное отношение к покупателям. Рекомендую.","x":"Машину ждали месяц через аукцион в Японии.","m":"Toyota C-HR","th":["term","docs"],"img":"r058_0","bo":0},{"d":"2025-10","a":"Сергей","t":"Заказал машину Фрида, пришëл в эту компанию по рекомендации от товарища, привезли за очень хорошие деньги, быстро за месяц с момента покупки и без проблем всë оформили. По приходу получил чистую машину, ещё помогли с регистрацией и документами в ГАИ. Всем доволен! Рекомендую, люди работают это сразу видно.","x":"Заказал машину Фрида, пришëл в эту компанию по рекомендации от товарища, привезли за очень хорошие деньги, быстро за месяц с момента покупки и без проблем всë оформили.","m":"Honda Freed","th":["term","docs","friend"],"img":"r059_0","bo":0},{"d":"2025-10","a":"Евгений","t":"Приобрёл свой новый автомобиль в Автозаказ28 и остался очень доволен. Отдельная благодарность Сергею и Олегу и всей их команде за профессиональный подход. Они мне подобрали автомобиль Nissan X-Trail 2022 в максимальной комплектации по приятной цене, всё прошло чётко, без скрытых платежей и подводных камней. Сделка была оформлена быстро и без лишних проблем. После сделки они всегда на связи 24/7 до получения автомобиля. Всем рекомендую этот автосалон, можно не сомневаться в их порядочности и компетенции.","x":"Они мне подобрали автомобиль Nissan X-Trail 2022 в максимальной комплектации по приятной цене, всё прошло чётко, без скрытых платежей и подводных камней.","m":"Nissan X-Trail","th":["price","touch","docs"],"img":"r060_0","bo":0},{"d":"2025-10","a":"Кристина","t":"Покупала здесь свою первую машину из Японии. Осталась в полном восторге! Мне помогли подобрать идеальный вариант — компактный, экономичный и в отличном состоянии. Весь процесс от выбора до доставки был максимально простым и понятным. Большое спасибо!","x":"Покупала здесь свою первую машину из Японии.","m":"","th":["first"],"img":"","bo":0},{"d":"2025-10","a":"Денис","t":"Хочу выразить огромную благодарность Сергею и его команде за бомбическую Toyota Voxy 2018 г., которую они нашли мне за день, четкая машина, без нареканий с хорошим аукционом. Автомобиль приобрел по программе трейд-ин, отдав свою Toyota Prius 2010 г. (ни разу меня не подводила и нового хозяина не подведет). Причём оценили по рыночной цене, когда в других компаниях оценивают ниже рыночной стоимости. Сергей был всегда на связи от момента заключения договора на подбор авто и до выдачи ключей от машины, и даже после передачи автомобиля он всегда на связи, интересуется покупкой. Сразу видно, команде Сергея не пофиг на клиента. Команда Сергея - Профессионалы с большой буквы, спецы в своей сфере, Люди слова и дела! К сожалению, таких людей и компаний сейчас очень мало. Всем рекомендую Автозаказ28!","x":"Сергей был всегда на связи от момента заключения договора на подбор авто и до выдачи ключей от машины, и даже после передачи автомобиля он всегда на связи, интересуется покупкой.","m":"Toyota Voxy","th":["price","touch","trade"],"img":"r062_0","bo":0},{"d":"2025-10","a":"Анлександр","t":"Обратился в данную компанию для приобретения автомобиля.\nСпециалист Сергей мастер своего дела!\nУчёл не просто все пожелания и требования к автомобилю, а приобрел шикарный вариант, на который даже не рассчитывали!\nНо самое главное, автомобиль был куплен на следующий день после подписания договора!\nЕщё больше удивила конечная стоимость автомобиля, вышло даже дешевле, чем рассчитывали!\nСергей был всегда на связи, информировал о каждом передвижении автомобиля.\nРекомендую данную компанию!\nПриобретать следующий автомобиль буду только через них, 100%!","x":"Но самое главное, автомобиль был куплен на следующий день после подписания договора!","m":"","th":["price","touch","report"],"img":"r063_0","bo":0},{"d":"2025-10","a":"Надежда","t":"Огромное спасибо Сергею и Олегу за проделанную работу! На всех этапах было легко и всё понятно! Ребята профессионалы своего дела! Очень довольна автомобилем тойота С- HR, просто шикардос!\nВсего месяц и моя давняя мечта сбылась с компанией Автозаказ28!\nВпредь буду обращаться только к ним!","x":"Всего месяц и моя давняя мечта сбылась с компанией Автозаказ28!","m":"Toyota C-HR","th":["term"],"img":"r064_0","bo":0},{"d":"2025-10","a":"Владимир","t":"Обратился в компанию Автозаказ28к ивану за приобретением авто.очень благодарен, оценка 5+, на каждом этапе очень четко и грамотно проконсультировал.буду рекомендовать своим друзьям и знакомым.успехов вам и процветания.","x":"Обратился в компанию Автозаказ28к ивану за приобретением авто.очень благодарен, оценка 5+, на каждом этапе очень четко и грамотно проконсультировал.буду рекомендовать своим друзьям и…","m":"","th":[],"img":"","bo":0},{"d":"2025-09","a":"Клиент","t":"Обратился к Сергею за помощью в приобретении автомобиля. Консультировали на всех этапах покупки. Машина пришла в указанные сроки, и в идеальном состоянии. А еще могут напоить кофем и накормить печеньками)) Спасибо большое Сергею за помощь в покупке. Успехов Вам и процветания.","x":"Обратился к Сергею за помощью в приобретении автомобиля.","m":"","th":["term"],"img":"r066_0","bo":0},{"d":"2025-09","a":"Евгения","t":"Огромное спасибо компании Автозаказ28 за нашего санкционного красавца. Работают быстро, качественно. Ответят на все интересующие Вас вопросы, подскажут, расскажут, посоветуют. В общем покупкой очень довольны и фирмой тоже. Теперь за автомобилем только к Вам. Рекомендую!","x":"Ответят на все интересующие Вас вопросы, подскажут, расскажут, посоветуют.","m":"","th":[],"img":"r067_0","bo":0},{"d":"2025-09","a":"Татьяна","t":"Дорогие ребята! Спасибо Вам за машину! Спасибо за человеческое отношение к водителю женщине! Спасибо за вашу огромную помощь в оформлении документов! Вы самая замечательная команда! Всем своим друзьям буду рекомендовать только вашу команду! Успехов Вам и процветания!","x":"Дорогие ребята!","m":"","th":["docs"],"img":"","bo":0},{"d":"2025-08","a":"Александр","t":"Все отлично! Мужики просто молодцы, все расскажут, все подскажут, кофем напо","x":"Мужики просто молодцы, все расскажут, все подскажут, кофем напо","m":"","th":[],"img":"","bo":0},{"d":"2025-08","a":"Клиент","t":"От всего сердца хочется поблагодарить Сергея и Олега за наш прекрасный автомобиль. Люди, действительно профессионалы. На всех этапах мы ощущали поддержку, по всем вопросам мгновенно получали ответы.","x":"От всего сердца хочется поблагодарить Сергея и Олега за наш прекрасный автомобиль.","m":"","th":[],"img":"r070_0","bo":0},{"d":"2025-08","a":"Владимир","t":"Сегодня получил долгожданный авто, компания отличная, все прозрачно. Полное сопровождение от покупки до доставки авто. Спасибо компании Автозаказ 28!","x":"Сегодня получил долгожданный авто, компания отличная, все прозрачно.","m":"","th":[],"img":"r071_0","bo":0},{"d":"2025-08","a":"Оксана","t":"Хочу сказать спасибо Сергею и Олегу за мою новую машину nissan x-trail 2020!все подобрали, рассказали, заказали и привезли... месяц и она моя! Ребята вообще работают четко и оперативно! Отдала своего филлдера+доплата, разве не сказка, никаких проблем! Сергей помогает и консультирует во всем, мне лично даже помог, направил в нужное направление для постановки на учет, т.к я не профи в этом деле!вообщем с вами работать одно удовольствие!","x":"месяц и она моя!","m":"Nissan X-Trail","th":["price","term","docs","trade"],"img":"r072_0","bo":0},{"d":"2025-07","a":"Светик","t":"Буквально несколько дней назад приехала наша красавица C-HR 2020 года в максимальной комплектации! А помогли нам в этом ребята из Автозаказ28!\nРаботать с Сергеем очень просто и понятно! Он помог подобрать лучшую машину в нашем бюджете! С круговым обзором, с подогревами сидений, комбинированным кожаным салоном, да еще и в тюнинге! Что может быть лучше для девушки!? И более того в автомобиле были дополнительные плюшки, а именно усилитель звука, просто бомба! Теперь музыку слушать одно удовольствие! А также был установлен японский видео регистратор с камерами переднего и заднего вида! Доставлена автовозом в кратчайший срок! Никаких скрытых платежей и подвохов нет! Все идеально! Перед покупкой Сергеем были предоставлены фотографии авто, что подтвердилось в реальности. Салон и кузов в идеале!\nЭто наша третья машина, приобретенная с Автозаказ28. Поэтому рекомендуем всем!\nА Автозаказ28 желаем дальнейшего процветания и развития! Спасибо за крутую тачку!","x":"Он помог подобрать лучшую машину в нашем бюджете!","m":"Toyota C-HR","th":["price","term","report","again"],"img":"r073_0","bo":0},{"d":"2025-07","a":"Марина","t":"Супер, доставили быстро, все отлично, спасибо!","x":"Супер, доставили быстро, все отлично, спасибо!","m":"","th":["term"],"img":"r074_0","bo":0},{"d":"2025-07","a":"Ксения","t":"Отличный сервис и надежность!\nНедавно решил приобрести автомобиль с аукциона и обратился в эту компанию — и ни разу не пожалел о своем выборе! Процесс покупки через аукцион оказался значительно проще, чем я ожидал, а специалисты компании помогли на каждом этапе.\nМенеджеры компании предоставили всю необходимую информацию о машине, проверили её историю. Все этапы сделки были прозрачными и понятными, и я всегда знал, что происходит с моей заявкой.\nАвтомобиль, который я купил, оказался в отличном состоянии, и, благодаря этой компании, я получил его по очень выгодной цене. Особенно радует, что мне не пришлось беспокоиться о технической части сделки — компания взяла на себя все вопросы, включая аукцион и оформление документов.\nОчень доволен сотрудничеством! С такой компанией можно смело работать, зная, что всё будет честно и профессионально. Обязательно обращусь снова, если буду искать автомобиль в будущем.","x":"Особенно радует, что мне не пришлось беспокоиться о технической части сделки — компания взяла на себя все вопросы, включая аукцион и оформление документов.","m":"","th":["docs"],"img":"r075_0","bo":0},{"d":"2025-06","a":"Александр","t":"Огромное спасибо компании Автозаказ 28 за приобретённый мне автомобиль Toyota Roomy с аукциона Японии. Всё в работе этой компании мне понравилось купили именно тот автомобиль, который я заказывал. Благодарю за быстроту, честность, вежливость","x":"Всё в работе этой компании мне понравилось купили именно тот автомобиль, который я заказывал.","m":"Toyota Roomy","th":[],"img":"r076_0","bo":0},{"d":"2025-06","a":"Denis","t":"Заказали автомобиль в данной компании. Всё, что связано с заказом доставкой и получением автомобиля выполнено на 5. Отдельно скажу, что на выбор компании огромное влияние для нашей семьи оказал Сергей позитивный, открытый, компетентный, отзывы о компании начали читать уже после принятого решения о заказе, что на меня не похоже.","x":"Всё, что связано с заказом доставкой и получением автомобиля выполнено на 5.","m":"","th":[],"img":"r077_0","bo":0},{"d":"2025-06","a":"Виктория","t":"Спасибо Сергею за качественный сервис. Подготовил все документы, сопровождение на всех этапах, всегда на связи, все подскажет, машину с автовоза сам принял и помыл, передал, вообще старательный тщательный добросовестный подход к делу. Молодец!","x":"Подготовил все документы, сопровождение на всех этапах, всегда на связи, все подскажет, машину с автовоза сам принял и помыл, передал, вообще старательный тщательный добросовестный…","m":"","th":["touch","docs"],"img":"r078_0","bo":0},{"d":"2025-06","a":"Юлия","t":"Хочу сказать огромное спасибо Сергею и Олегу за машину! Замечательная работа по доставке, и кстати у ребят очень вкусный кофе. Еще раз спасибо","x":"Замечательная работа по доставке, и кстати у ребят очень вкусный кофе.","m":"","th":[],"img":"","bo":0},{"d":"2025-06","a":"Ilya","t":"Заказал здесь авто, сам я с Новокузнецка, заказал Toyota C-HR, некоторые отговаривали и рекомендовали другие конторы, но мне очень запала именно эта машина и связавшись с Сергеем он мне все максимально о ней рассказал, прислал кучу фото, я сразу решил брать здесь, и не разу не пожалел!\nСергей всегда на связи, дал все инструкции ответил на все мои вопросы, полностью сопровождал все этапы! И вот 06.06 я получил с автовоза мою машину, все в идеале, я переживал что будет ржавчина и коцки серьезные, в итоге днище чистое в антикоре, все работает, коцки не значительные, все как в аукционном листе, машина по состоянию как с салона, все четко цена как указана никаких доп платежей, все под ключ было как и договорились, я полностью доволен, рекомендую терь всем своим друзья и знакомым именно эту фирму. Огромное спасибо!","x":"И вот 06.06 я получил с автовоза мою машину, все в идеале, я переживал что будет ржавчина и коцки серьезные, в итоге днище чистое в антикоре, все работает, коцки не значительные, все…","m":"Toyota C-HR","th":["price","touch","report"],"img":"r080_0","bo":0},{"d":"2025-05","a":"Наталья","t":"Хочется выразить огромную благодарность Сергею за подбор автомобиля, подробно и добросовестно все рассказал, показал, все объяснил, а так же учел мои пожелания в покупке. Привезли автомобиль даже быстрее и дешевле, чем рассчитывала.\nПостоянно сообщал, где он находится и что происходит. Все сделал честно и открыто. Очень довольна покупкой. Огромное спасибо Сергею! профессионал своего дела! рекомендую всем!","x":"Привезли автомобиль даже быстрее и дешевле, чем рассчитывала.","m":"","th":["price","term"],"img":"r081_0","bo":0},{"d":"2025-05","a":"Айрат","t":"Я очень благодарен Олегу Валерьевичу и Сергею Олеговичу за их труд, за ответственный подход к своему делу. Я доволен проделанной работой, авто доставили по моим критериям, и по цене ниже сложившейся рыночной! Спасибо ребята!","x":"Я доволен проделанной работой, авто доставили по моим критериям, и по цене ниже сложившейся рыночной!","m":"","th":[],"img":"","bo":0},{"d":"2025-05","a":"Алексей","t":"Хочу выразить огромную благодарность Сергею и поделиться своим положительным опытом. Обратился в Автозаказ 28, хотел узнать о возможности привезти данный автомобиль. Зашел к ним офис, Сергей и его отец все рассказалии обьяснили все в подробностях, чем рассположили к себе и сразу было понятно что они знаю свое дело. Они предложили данный автомобиль и он у них был уже куплен на аукционе и он понравился нам, осталось только привезти его.\nМы заказали автомобиль, да автомобиль санкционный пришлось подождать и набраться терпения, спасибо кстати Сергею, который подбадривал и рассказал все на всех этапах.\nВыражаю огромную благодарность команде за профессионализм и оперативность. Теперь я точно знаю, к кому обращаться в будущем! Однозначно Рекомендую 100%! Не бойтесь обращайтесь. Следующий автомобиль закажу для себя и только у Вас.","x":"Они предложили данный автомобиль и он у них был уже куплен на аукционе и он понравился нам, осталось только привезти его.","m":"","th":[],"img":"r083_0","bo":0},{"d":"2025-05","a":"Кристина","t":"Спасибо огромное Сергею за оперативность, подход к каждому покупателю, все четко по делу! Очень довольны покупкой, все на высшем уровне","x":"Очень довольны покупкой, все на высшем уровне","m":"","th":[],"img":"r084_0","bo":1},{"d":"2025-05","a":"Клиент","t":"Спасибо большое очень доволен автомобилем, Сергею отдельное спасибо, всегда на связи, разьеснит если что-то не понятно","x":"Спасибо большое очень доволен автомобилем, Сергею отдельное спасибо, всегда на связи, разьеснит если что-то не понятно","m":"","th":["touch"],"img":"r085_0","bo":0},{"d":"2025-05","a":"Сергей","t":"Спасибо Сергей, -чётко, оперативно.. Без замечаний","x":"Без замечаний","m":"","th":[],"img":"","bo":0},{"d":"2025-05","a":"Галина","t":"Огромная благодарность Сергею за доставку автомобиля из Японии. Быстро, без заморочек, только подписали договор, а машина уже у меня в гараже. Мы очень довольны сервисом.","x":"Быстро, без заморочек, только подписали договор, а машина уже у меня в гараже.","m":"","th":[],"img":"","bo":0},{"d":"2025-05","a":"Anton","t":"Искали компактную, но удобную машинку – остановились на Honda Fit. Решили не усложнять себе жизнь с поиском на местном рынке или с самостоятельным импортом и обратились сюда. И правильно сделали! Сергей подобрал отличный вариант, да и по цене вышло хорошо. Даже очень. Всё прошло гладко – никаких скрытых проблем или неожиданных косяков. Сергей всегда был на связи, если что-то было непонятно, разжёвывал всё подробно и по делу. Документы оформили быстро, растаможку сделали без проблем. Все платежи проходили поэтапно - за аукцион, таможню, доставку - ровно в тот момент, когда это было нужно. Никаких скрытых взносов или неожиданных переплат.\nЕсли короче: хотите без головной боли купить японский автомобиль – советую Автозаказ28. Моя водитель счастлива, а значит, и я спокоен. Спасибо за хорошую работу!","x":"Сергей подобрал отличный вариант, да и по цене вышло хорошо.","m":"Honda Fit","th":["price","touch","docs"],"img":"r088_0","bo":0},{"d":"2025-05","a":"Клиент","t":"Напишу отзыв честный и от души. Когда хочется поделиться эмоциями и посоветовать другим. Муж решил мне купить новый автомобиль. Не знали куда обратиться …. Друг посоветовал обратиться к Сергею. Так как сам через его фирму привозил из Японии для себя уже не одну машину.\nМы обрисовали все свои «хотелки» к машине. Сергей очень четко, профессионально приобрел нам машину. Сопровождая от аукциона и до самого дома нас и наш Harrier. Пришлось конечно ждать автомобиль, так как он санкционный. Тут со стороны Сергея была оказана и моральная поддержка, подбадривая и успокаивая, что все будет хорошо! Нужно немного набраться терпения ( так как мы девушки совсем нетерпеливые. Нужно вот здесь и сейчас)\nВот и приехал мой красавчик который просто идеальный. Что внутри, что снаружи. Теперь покупая очередную машину, я не раздумывая пойду только в Автозаказ28.\nСпасибо, Сергей!","x":"Сопровождая от аукциона и до самого дома нас и наш Harrier.","m":"Toyota Harrier","th":["again","friend"],"img":"r089_0","bo":0},{"d":"2025-05","a":"Эльвира","t":"Спасибо большое семейной дружной команде! Я очень рада! Машина шустрая, маневренная, высокая, в езде комфортная. 19 апреля куплена на аукционе, 9 мая вручили ключи)) РЕКОМЕНДУЮ 100%. Сергей Олегович знает свое дело на + и даже больше! Будем обращаться к вам!","x":"19 апреля куплена на аукционе, 9 мая вручили ключи)) РЕКОМЕНДУЮ 100%.","m":"","th":[],"img":"r090_0","bo":0},{"d":"2025-04","a":"Лариса","t":"Я хочу выразить свою искреннюю благодарность Сергею Пономареву и компании Автозаказ 28 за помощь в приобретении автомобиля из Японии. Toyota Corolla Cross -выбор, который оправдал все ожидания. С момента нашего первого общения я поняла, что нахожусь в надёжных руках профессионала высокого уровня. Это было одно из лучших решений в моей жизни обратиться к Сергею и его команде. Сергей подробно объяснил все этапы сделки. Новый автомобиль приобретен по трейд- ин ( обмен своего старого автомобиля на новый с доплатой), что сэкономило время и силы. Не нужно было искать покупателя на старое авто и заниматься сотнями других хлопот. Сергей взял на себя все организационные моменты, связанные с оформлением документов. Благодаря его помощи, весь процесс прошел гладко и быстро. Теперь я наслаждаюсь свои новым автомобилем! Рекомендую компанию Автозаказ 28 всем, кто планирует покупку авто из Японии - вы не пожалеете! Сергей, спасибо за вашу работу!\nP.S. через три года договорились о новой встрече","x":"Новый автомобиль приобретен по трейд- ин ( обмен своего старого автомобиля на новый с доплатой), что сэкономило время и силы.","m":"Toyota Corolla Cross","th":["price","docs","trade"],"img":"r091_0","bo":0},{"d":"2025-04","a":"Макс","t":"Хочу поделиться своим положительным опытом сотрудничества с АВТОЗАКАЗ28. Пришли, рассказали что хотим. Нам даже дали прокатиться на таком же тестовом авто.\nМы заказали автомобиль, о котором давно мечтали приобрести, и они привезли его в кратчайшие сроки. Честный аукционный автомобиль.\nВыражаю огромную благодарность команде за профессионализм и оперативность. Ребята действительно молодцы. Теперь я точно знаю, к кому обращаться в будущем! Однозначно Рекомендую!","x":"Честный аукционный автомобиль.","m":"","th":["term"],"img":"r092_0","bo":0},{"d":"2025-04","a":"Артем","t":"Огромное спасибо команде «Автозаказ28» за новый автомобиль в семье Toyota Yaris!\nС первой минуты общения было ясно — здесь работают профессионалы. В компании сразу поняли, что я ищу, предложили несколько отличных вариантов, а оформление прошло быстро и гладко.\nОсобенно порадовала поддержка на каждом этапе: отвечали оперативно, подробно объясняли детали и всегда были на связи. Toyota Yaris оказалась именно такой, как я хотел — идеальное сочетание качества и цены.\nЕсли вам нужен надёжный автомобиль без лишних хлопот — уверенно рекомендую «Автозаказ28». Здесь действительно знают своё дело!","x":"С первой минуты общения было ясно — здесь работают профессионалы.","m":"Toyota Yaris","th":["touch","docs"],"img":"r093_0","bo":0},{"d":"2025-04","a":"Кристина","t":"Профессионалы с большой буквы! Благодарим Сергея за идеально выполненную работу, человек находка! Очень вежливый, работать с ним одно удовольствие! Заказали машину и уже спустя 4 недели забрали нашего красавца в семью. Спасибо вам за ваш профессионализм","x":"Заказали машину и уже спустя 4 недели забрали нашего красавца в семью.","m":"","th":["term"],"img":"r094_0","bo":0},{"d":"2025-03","a":"Вадим","t":"Работать с Сергеем одно удовольствие, всегда подскажет, расскажет, поможет. Была мечта купить TOYOTA C-HR встретились он подобрал нам данный автомобиль в максимальной комплектации все устроило C-HR ПУШКА. Поэтому кто хочет купить автомобиль своей мечты безусловно обращайтесь в эту компанию Автозаказ28. БОЛЬШОЕ СПАСИБО И ПРОЦВЕТАНИЯ ВАМ!","x":"Работать с Сергеем одно удовольствие, всегда подскажет, расскажет, поможет.","m":"Toyota C-HR","th":[],"img":"r095_0","bo":0},{"d":"2025-03","a":"Александр","t":"Хочу выразить огромную благодарность Сергею, за услуги оказанные при подборе, покупки и привозу автомобиля из японии в россию. 20.02.2025г подписали договор, обговорили комплектацию, и т.д. 21.02.2025г машина была куплена на аукционе в японии и 23.03.2025г мы забрали автомобиль в г. Благовещенск. За все время от подбора до передачи машины нам, Сергей был на связи, и информировал нас о каждом этапе покупки авто, предоставляя фотовидеоотчет. В конце хочу еще раз поблагодарить Сергея, и всем рекомендую обращаться в Автозаказ28, кто хочет купить честный автомобиль из японии.","x":"За все время от подбора до передачи машины нам, Сергей был на связи, и информировал нас о каждом этапе покупки авто, предоставляя фотовидеоотчет.","m":"","th":["touch","report"],"img":"r096_0","bo":0},{"d":"2025-03","a":"Клиент","t":"Хочу выразить огромную благодарность Сергею за помощь в привозе автомобиля из Японии! Всё прошло идеально: от подбора машины до оформления документов и доставки. Сергей действовал профессионально, ответственно и всегда держал в курсе событий. Сроки, стоимость и условия полностью совпали с обещанным — никаких скрытых нюансов или задержек.\nОсобо отмечу его умение решать вопросы оперативно и внимательно относиться к пожеланиям клиента. Такой уровень надёжности и четкости сейчас редко встретишь!\nСмело рекомендую Сергея тем, кто ищет честного, опытного агента для покупки авто из Японии. Он действительно работает на результат и заслуживает доверия. Спасибо за отличный сервис!","x":"Сроки, стоимость и условия полностью совпали с обещанным — никаких скрытых нюансов или задержек.","m":"","th":["price","touch","docs"],"img":"","bo":0},{"d":"2025-03","a":"Клиент","t":"Огромная благодарность Сергею.\nвсе получилось в сроки. Все этапы покупки прошли без каких либо нюансов\nМашинка огонь большое спасибо ))","x":"Все этапы покупки прошли без каких либо нюансов","m":"","th":["term"],"img":"r098_0","bo":0},{"d":"2025-02","a":"Алексей","t":"Эта компания - яркий пример того, как должен работать бизнес. Имея дело с ними, я почувствовал, что мои потребности и интересы находятся на первом месте. Ответственность, оперативность и высший стандарт обслуживания - вот что делает эту компанию непревзойденной. Огромное спасибо за прекрасный опыт!","x":"Имея дело с ними, я почувствовал, что мои потребности и интересы находятся на первом месте.","m":"","th":[],"img":"r099_0","bo":0},{"d":"2025-02","a":"Клиент","t":"Ребята капитальные красавчики. Во первых подобрали именно ту комплектацию, которая нужна была мне. Во вторых, привезли машину за 1.5 месяца ( за это вообще отдельное спасибо и низкий поклон ). У меня есть реальные истории моих знакомых, которым другие компании везли автомобили по 5 месяцев.\nМашина была оплачена 08.11.24, а приехала в порт Владивостока 25.12.2024. Мною были сразу-же уплачены все необходимые сборы и пошлины. В итоге, через 3 дня человек лично полетел во Владивосток, и забрали машину с СВХ. Потом наступили Новогодние праздники, машина простояла несколько дней на охраняемой стоянке и была поставлена на первый-же в этом году автовоз. В Итоге я получил машину 07.01.2025.\nМужики реально знают свою работу и делают её максимально профессионально. Отвечая при этом на все вопросы, оставаясь всегда на связи. И днём и вечером.\nОднозначно рекомендую данную компанию к сотрудничеству, при заказе авто с Японии.","x":"Во первых подобрали именно ту комплектацию, которая нужна была мне.","m":"","th":["touch"],"img":"r100_0","bo":0},{"d":"2025-02","a":"Марина","t":"Выражаем БОЛЬШУЮ благодарность за организацию покупки автомобиля! Всё выполнено в оговоренные договором сроки, машина в отличном состоянии, помощь была на каждом этапе покупки! Однозначно рекомендуем!","x":"Всё выполнено в оговоренные договором сроки, машина в отличном состоянии, помощь была на каждом этапе покупки!","m":"","th":[],"img":"r101_0","bo":0},{"d":"2025-02","a":"Арсен","t":"Заказывал автомобиль Харриер, уже вторую машину в семью,2 месяца ожидания и автомобиль прибыл в отличном состоянии, назвал в честь продавца свое дерево, «Серёга Бансай!» процветания бизнесу!","x":"Заказывал автомобиль Харриер, уже вторую машину в семью,2 месяца ожидания и автомобиль прибыл в отличном состоянии, назвал в честь продавца свое дерево, «Серёга Бансай!» процветания бизнесу!","m":"Toyota Harrier","th":["again"],"img":"r102_0","bo":0},{"d":"2025-01","a":"Сергей","t":"Планировал покупку автомобиля Honda Vezel. Знакомый посоветовал обратится за покупкой машины к Сергею. С самой первой встречи установились доверительные отношения. Сергей всегда был на связи, всегда своевременно давал актуальную информацию, очень много помогал, подсказывал как и что нужно сделать. Автомобиль просто превзошёл мои ожидания, как по цене (она вышла намного ниже, чем по рынку) так и по качеству (11т пробег, 2020 год, хорошая оценка аукциона). По оплате тоже все отлично, лишних денег не берет, Сергей предоставлял все чеки, что и за что я оплачивал, так что все максимально честно, только обговоренная оплата за работу. По срокам тоже все супер, машина пришла быстро и без задержек, даже на права ещё сдать не успел. Учитывая, что это первая моя машина, Сергей помог мне её немного подготовить, мы вместе с ним выбрали зимнюю резину и сразу переобулись и после этого он довёз меня на машине домой, так как прав у меня ещё нет. Также дал много контактов к кому можно обратиться для дальнейшей подготовки машины к комфортному вождению и сказал, что он тоже на связи, если будут какие-то вопросы. Всем рекомендую обращаться за покупкой автомобиля к Сергею. Лично тоже буду всем рекомендовать. Покупкой автомобиля остался очень доволен Спасибо огромное за проделанную работу!","x":"Автомобиль просто превзошёл мои ожидания, как по цене (она вышла намного ниже, чем по рынку) так и по качеству (11т пробег, 2020 год, хорошая оценка аукциона).","m":"Honda Vezel","th":["price","touch","term","first","friend"],"img":"r103_0","bo":0},{"d":"2024-12","a":"Андрей","t":"Все устроило\nРекомендую данное место","x":"Все устроило","m":"","th":[],"img":"","bo":0},{"d":"2024-12","a":"Михаил","t":"Нашёл компанию случайно, покупка машины была почти спонтанной, из -за скачка проклятой зелёной бумажки. Работал с Сергеем. Впечатления только положительные. Договор с конечной ценой, это раз. Предоплата была всего 30 т.р.это два. Не надо было носиться по банкам, оплачивать инвойсы и томиться в ожидании без денег и без машины. Это три. Для меня это большой плюс. Машина была куплена компанией и стояла в Японии. Вместе следили за кораблём. Всегда на связи и всегда отвечали на все мои вопросы. Даже таможню и утиль за меня заплатили, что тоже было удобно, просто потом это вошло в стоимость авто, не подумайте, что люди занимаются благотвориткльностью))). Конечно было немного волнительно, но всё хорошо. Парни хорошо делают свою работу, очень рекомендую для сотрудничества. Такого вот красавца мне привезли.","x":"Всегда на связи и всегда отвечали на все мои вопросы.","m":"","th":["price","touch"],"img":"r105_0","bo":0},{"d":"2024-12","a":"Закарик","t":"Работали с Сергеем над приобретением нового авто. Машинка пришла быстро, сама просто пушка, летает. За приобретением второго авто уже знаем куда обращаться. Огромное спасибо за проделанную работу!","x":"Работали с Сергеем над приобретением нового авто.","m":"","th":["term","again"],"img":"","bo":0},{"d":"2024-12","a":"Елена","t":"Большое спасибо Сергею\nНовую машинку мы приобрели с его помощью, на протяжении всего времени он держал нас в курсе, на каком этапе находится машина и т.д.\nОчень вежлив и коммуникабелен, с его помощь всë оформление оказалось не таким сложным, всë по честному как обговаривали, машинка классная, как и хотели, надеюсь оправдает наши ожидания\nСпасибо Сергею и его команде, рекомендую от души","x":"Новую машинку мы приобрели с его помощью, на протяжении всего времени он держал нас в курсе, на каком этапе находится машина и т.д.","m":"Daihatsu Rocky","th":["report","docs"],"img":"r107_0","bo":0},{"d":"2024-12","a":"Юрий","t":"Спасибо огромное Сергею за проделанную работу! Машину доставили в назначенный срок, в отличном состояние. Очень вежливый и ответственный молодой человек, приятно с такими работать. Теперь заказывать авто будем только через эту компанию!","x":"Машину доставили в назначенный срок, в отличном состояние.","m":"","th":["term"],"img":"r108_0","bo":0},{"d":"2024-12","a":"Андрей","t":"Огромное спасибо Олегу и Сергею за отличную работу! Ребята профессионалы, постоянное информирование и консультации от доставки из Японии до постановки на учёт. Авто забрал из Владивостока ровно через 2 недели после подписания договора. Состоянием машины полностью доволен, всё как в аукционе. До Иркутска добрался своим ходом, авто в полном порядке. Олегу и Сергею удачи, успехов в работе и побольше клиентов)","x":"Авто забрал из Владивостока ровно через 2 недели после подписания договора.","m":"","th":["docs"],"img":"","bo":0},{"d":"2024-12","a":"Екатерина","t":"Выражаю большую благодарность Сергею и Олегу! Машина превзошла все мои ожидания! Спасибо вам огромное за помощь в выборе данного автомобиля! Вы всегда были со мной на связи, оперативно отвечали! Даже по моей просьбе поставили зимнюю резину, помыли, все рассказали, объяснили! Остались только положительные эмоции от общения с вами! Успехов и процветания вам!","x":"Вы всегда были со мной на связи, оперативно отвечали!","m":"","th":["touch"],"img":"","bo":0},{"d":"2024-12","a":"Иван","t":"Здравствуйте уважаемые автолюбители. Несколько слов об опыте сотрудничества с ИП Пономаревым С.О. Когда задался вопросом приобретения санкционного автомобиля из Японии, в первую очередь искал надежного посредника, с хорошей репутацией. Но толи они не вызывали доверия, толи явно завышали свои тарифы. (Одна известная фирма в качестве гарантии требовала 300 т.р. за 100% успех по доставке запрещённого авто).\nИ вот при обзвоне потенциальных исполнителей, встретился с Сергеем – молодой парень, но с большим опытом работы, который не сидит где-то в кабинете, а реально занимается своими машинами на авторынке и в случае чего не свалит со своего «офиса» и не выключит телефон.\nАгент дал весь расклад по статистике, рынку, модели, подобрал мой вариант и подписали договор. Пока ждал, Серега был всегда на связи, вопрос-ответ, любая консультация.\nМашина пришла соответствующая ожиданиям. Вчера на почту пришёл ЭПТС. Хорошо налаженные контакты и связи позволили в короткие сроки организовать работы по растаможке.\nВсем удачи на дорогах, а Сергею – успехов ему и его предприятию. Следующий автомобиль только через «Автозаказ 28».","x":"Когда задался вопросом приобретения санкционного автомобиля из Японии, в первую очередь искал надежного посредника, с хорошей репутацией.","m":"","th":["touch","term","docs"],"img":"","bo":0},{"d":"2024-12","a":"Сергей","t":"Сотрудничество с компанией \"Автозаказ 28\" оставило приятные впечатления. Привезли автомобиль из Японии в хорошем состоянии, и в короткие сроки. Я доволен.","x":"Сотрудничество с компанией \"Автозаказ 28\" оставило приятные впечатления.","m":"","th":["term"],"img":"","bo":0},{"d":"2024-12","a":"Полина","t":"Купила свою первую в жизни машину у Сергея. Все было замечательно, Сергей все показал, рассказал. Готов был ко всем проверкам. Идет на контакт очень легко, с ним приятно общаться. Помогал мне до самой постановки на учет, тк нет опыта)\nСоветую","x":"Купила свою первую в жизни машину у Сергея.","m":"","th":["docs","first"],"img":"","bo":0},{"d":"2024-11","a":"Василий","t":"Совершенно случайно на рынке встретил Сергея. После разговора с ним мне был подобран автомобиль в Японии. Сергей на протяжении всей сделки и вплоть до получения номеров в ГИБДД давал мне корректирующие консультации, за что ему спасибо. Автомобиль пришел в идеальном состоянии, по сути новый, как и обещал Сергей. Честность поражает, в машине обнаружил родной японский регистратор, весь ремкомплект в багажнике, новую запечатанный японский освежитель салона. Машина при получении мной была вымыта, немного заправлена. Это очень приятно. Сергей просто герой в моих глазах","x":"Совершенно случайно на рынке встретил Сергея.","m":"","th":["docs"],"img":"","bo":0},{"d":"2024-11","a":"Екатерина","t":"В компании-отличный сервис, профессионализм и просто человеческое отношение к клиентам! Я впервые покупала машину на аукционе в Японии. Сергей - настоящий эксперт! Разъяснил все детали предстоящей процедуры, помог выбрать оптимальный вариант под мой бюджет, сопровождал все этапы оплаты, консультировал по любым вопросам. В итоге машина прибыла в срок и досталась мне даже за меньшие деньги, чем я ожидала. Очень круто, что в нашем городе есть такие надежные представители автобизнеса!","x":"Я впервые покупала машину на аукционе в Японии.","m":"","th":["term","first"],"img":"","bo":0},{"d":"2024-11","a":"Евгений","t":"Приобрели уже второй автомобиль в компании автозаказ28. Ребята, а в особенности Сергей, знают свое дело! Получилось все быстро, четко без каких-либо косяков. Всем доволен","x":"Приобрели уже второй автомобиль в компании автозаказ28.","m":"","th":["again"],"img":"","bo":0},{"d":"2024-11","a":"Анастасия","t":"Обратились в данную компанию для приобретения Джима с аукциона. Сергей скидывал достаточно вариантов, подходящие под наши критерии. Учитывал все пожелания, оперативно отвечал на все возникающие вопросы. Вся оплата прозрачная, инвойс, таможня оплачивались через банк. Машина пришла в указанные сроки. По стоимости машины - получилось даже дешевле от обговариваемой суммы (на 50-100 тысяч)\nПриятно было сотрудничать.","x":"Обратились в данную компанию для приобретения Джима с аукциона.","m":"Suzuki Jimny","th":["price","touch","term"],"img":"","bo":0},{"d":"2024-11","a":"Larisa","t":"Меньше месяца назад, мы заехали в автозаказ 28, просто посмотреть, как выглядит Тойота С-HR. Нам всё рассказали, показали и даже тест-драйв на аналогичном авто дали, только чёрного цвета. Не раздумывая, мы заключили договор, где все риски были на Автозаказе 28. И вот Сегодня получили нашу Тойоту С-HR. Супер. Эмоции-полный восторг, всё классно, стильно, очень красивый салон, состояние нового автомобиля. Технические моменты-безупречно и идеально. Автомобиль привезли меньше чем за месяц. Всё как в договоре. Какие вы молодцы! Спасибо огромное! Рекомендуем всем","x":"Не раздумывая, мы заключили договор, где все риски были на Автозаказе 28.","m":"Toyota C-HR","th":["term"],"img":"","bo":0},{"d":"2024-11","a":"Светлана","t":"Хочу выразить огромную благодарность за приобретенный автомобиль. В компанию Автозаказ28 обратилась совершенно случайно и не пожалела. Особая признательность хотелось бы выразить Сергею за высокий уровень обслужтвания и профессионализм.\nПервоначально мы определились с моделью, которую хотели бы приобрести. Мы также учли бюджет, который у нас был, и начали искать подходящие предложения.\nПосле этого мы подписали договор и внесли предоплату. Я получила всю необходимую информацию о стоимости автомобиля, налогах, таможенных сборах и других возможных расходах. Сергей подробно объяснил мне все этапы: от выбора автомобиля на аукционе до его доставки в Россию. Он всегда был готов помочь и ответить на все мои вопросы. Автомобиль прибыл в идеальном состоянии, и первое впечатление было просто потрясающим. Машина оказалась даже лучше моих ожиданий.Сергей и Олег помогли не только с приобритением машины, но и с поиском и установкой резины. Работать с вами было одно удовольствие.","x":"Первоначально мы определились с моделью, которую хотели бы приобрести.","m":"","th":["price"],"img":"","bo":0},{"d":"2024-11","a":"Александр","t":"Отличная компания. Машина пришла в срок. Состояние отличное.","x":"Отличная компания.","m":"","th":["term"],"img":"","bo":0},{"d":"2024-11","a":"Дмитрий","t":"Покупали у парней авто toyota raize по обмену. Что можно сказать. Все отлично постоянно на связи 24/7 Сергей информировал по всему маршруту движения авто из Японии. Будем обращаться еще. Огромное спасибо!","x":"Все отлично постоянно на связи 24/7 Сергей информировал по всему маршруту движения авто из Японии.","m":"Toyota Raize","th":["touch","report","trade"],"img":"r123_0","bo":1},{"d":"2024-10","a":"Андрей","t":"Сергей ответственный, честный и порядочный. Отлично знающий своё дело. Предложил хорошую машину. Покупкой доволен. Рекомендую обращаться к нему, не подведёт. Сергей, персональное Спасибо!","x":"Сергей ответственный, честный и порядочный.","m":"","th":[],"img":"","bo":0},{"d":"2024-10","a":"Тамара","t":"Решили приобрести авто. Нашли объявление в Дроме. Созвонились с Сергеем, приехали в офис, нам всё рассказали, все нюансы, на все вопросы ответили. Составили договор, внесли предоплату и стали ждать авто. Сергей всегда был на связи 24/7, всё рассказывал. По приходу машины, заплатили оставшуюся часть. Воспользовались услугами этой компании и ни разу не пожалели. От сотрудничества остались только приятные воспоминания. Всем рекомендую, очень ответственные люди.","x":"Сергей всегда был на связи 24/7, всё рассказывал.","m":"","th":["price","touch"],"img":"","bo":0},{"d":"2024-10","a":"Евгений","t":"Хочу поблагодарить Сергея и Олега! Привезли машину! Все хорошо! Всегда Сергей был на связи, все доходчиво объяснял! По срокам выходит как и говорят! Советую! Обращайтесь!","x":"Всегда Сергей был на связи, все доходчиво объяснял!","m":"","th":["touch"],"img":"","bo":0},{"d":"2024-10","a":"Валерий","t":"Обратился за покупкой автомобиля в компанию «Автозаказ 28». Купили, привезли всё отлично! По срокам месяц после покупки, как и обещали. Особенно хочу отметить Сергея Пономарёва! Он большой молодец! Всегда на связи, всё рассказывал и всё объяснял. Большое всем спасибо! Всем рекомендую обращаться в эту компанию.","x":"По срокам месяц после покупки, как и обещали.","m":"","th":["touch","term"],"img":"","bo":0},{"d":"2024-10","a":"Алексей","t":"Я недавно воспользовался услугой по подбору и покупке автомобиля, и хочу поделиться своим опытом. С самого начала процесса я увидел профессионализм и внимание к деталям, которые продемонстрировал специалист по имени Сергей. Я заранее знал какую модель я хочу и в каком ценовом диапазоне. Сергей провели тщательный анализ рынка, чтобы найти лучшую ценовую предложение и нашел данный автомобиль. Который был забронирован, выкуплен и доставлен ко мне в целости и сохранности, раньше установленного срока.\nПроцесс покупки был организован безупречно. Все документы были подготовлены заранее, и я не столкнулся ни с какими сложностями или задержками. Сергей был всегда на связи, предоставлял мне актуальную информацию о ходе процесса и отвечая на все мои вопросы.\nАвтомобиль прибыл в хорошем состоянии и доставлен вовремя. Все это стало возможным благодаря профессиональной работе.\nЯ хочу выразить свою благодарность за предоставленную услугу.","x":"Сергей был всегда на связи, предоставлял мне актуальную информацию о ходе процесса и отвечая на все мои вопросы.","m":"","th":["touch","term","docs"],"img":"","bo":0},{"d":"2024-10","a":"Владимир","t":"Отзывчивость и интересы заказчика стоят на первом месте! Все, что было оговорено - цена, сроки, качество авто выполнено на отлично. Уже по прибытию авто попросил комплект зимней резины в сборе-и пожалуйста вам-увёз с собой по нормальной цене. Сергей Олегович спасибо Вам за Вашу работу. По авто, помощи по всем возникшим вопросам, по отношению 5 из 5!","x":"Отзывчивость и интересы заказчика стоят на первом месте!","m":"","th":[],"img":"","bo":0},{"d":"2024-10","a":"Andrey","t":"Хочу выразить благодарность команде Автозаказ28 за проделанную работу при подборе и привозу автомобиля! Ребята были на связи 24/7, консультировали по всем вопросам. Спасибо!","x":"Ребята были на связи 24/7, консультировали по всем вопросам.","m":"","th":["touch"],"img":"","bo":0},{"d":"2024-09","a":"Дмитрий","t":"Хочу выразить огромную благодарность за отличную работу. Сергей и Олег были на связи на всех этапах сделки, предоставляя мне актуальную информацию о статусе заказа. Получил именно тот автомобиль, который хотел, в отличном состоянии и по разумной цене.","x":"Сергей и Олег были на связи на всех этапах сделки, предоставляя мне актуальную информацию о статусе заказа.","m":"","th":["touch"],"img":"","bo":0},{"d":"2024-09","a":"Ольга","t":"Нашла объявление в Дроме, сразу созвонились с Сергеем, он подробно все рассказал об авто и сроках, сразу видно профессионал своего дела. Был выбор Harrier 2021 и 2020 год, я выбрала последний где меньше пробег. Подписали договор, где сумму зафиксировали в рублях, это очень удобно в условиях нынешней ситуации с курсом. Внесла предоплату и ждала своего красавца. Пошлину оплатила по приходу авто на таможню сама, оставшуюся часть при получении авто.\nХарек идеальный, как собственно и было заявлено в аукционном листе, и даже превзошел ожидания. Сергей всё время был на связи 24/7. Так как машина санкционная, пришлось подождать автомобиль, но он того стоил\nСпасибо за сотрудничество, все прошло очень комфортно, всем рекомендую!\nСергей, вам отдельное СПАСИБО за запаску и за натуральный японский кофе","x":"Сергей всё время был на связи 24/7.","m":"Toyota Harrier","th":["price","touch","report"],"img":"","bo":0},{"d":"2024-09","a":"Андрей","t":"Воспользовался услугами Автозаказ28 и не пожалел, остался очень доволен. При оформлении заказа сразу заключается договор, оговариваются все условия, в том числе и конечная сумма автомобиля в г. Благовещенске, что я считаю очень важно. Все платежи прозрачны, денег наперед не требуют. Расчёт окончательный только при получении машины. Составляют акт приёма передачи автомобиля. Заказал автомобиль с аукциона с оценкой 4,5 балла с небольшим пробегом. Получил практически новый автомобиль. Сергей постоянно был на связи, всё объяснял. От сотрудничества за время пути автомобиля остались только приятные эмоции. Рекомендую покупки автомобиля в этой фирме. Спасибо и дальнейшего процветания.","x":"При оформлении заказа сразу заключается договор, оговариваются все условия, в том числе и конечная сумма автомобиля в г.","m":"","th":["price","touch","docs"],"img":"r132_0","bo":1},{"d":"2024-08","a":"Куаныш","t":"Спасибо Сергею огромное за помощь в приобретении машины. Все сделал быстро и качественно буду всегда к нему обращаться.","x":"Все сделал быстро и качественно буду всегда к нему обращаться.","m":"","th":[],"img":"","bo":0},{"d":"2024-08","a":"Елена","t":"Решили приобрести новую машину, выбор пал на Harrier, сами с Владивостока, заключили договор с местной кампанией, но как то все шло не очень хорошо, муж случайно на дроме увидел объявление и написал Сергею. Через несколько дней раздумий решили приобрести авто через него. Все прошло отлично, полное сопровождение до постановки на учет, всегда был на связи, отвечал на все возникающие вопросы! Машина пришла даже лучше, чем мы ожидали. Шла почти два месяца.\nМы с мужем в восторге! Однозначно рекомендуем!","x":"Решили приобрести новую машину, выбор пал на Harrier, сами с Владивостока, заключили договор с местной кампанией, но как то все шло не очень хорошо, муж случайно на дроме увидел…","m":"Toyota Harrier","th":["touch","docs"],"img":"","bo":0},{"d":"2024-08","a":"Елена","t":"Хочу сказать огромное спасибо Сергею за хорошую, качественную работу. Обратилась в данную компанию просто почитав положительные отзывы и не пожалела об этом. После подписания договора началась работа по подбору авто и Сергей всегда был на связи, всё подробно объяснял и консультировал. Буду вас рекомендовать с большим удовольствием.","x":"После подписания договора началась работа по подбору авто и Сергей всегда был на связи, всё подробно объяснял и консультировал.","m":"Daihatsu Rocky","th":["touch"],"img":"","bo":0},{"d":"2024-08","a":"Михаил","t":"Спосибо сработали отлично машина на 4 бала полностью оправдала ожидания. Отдельно хочу поблагодарить Сергея Олегович Понамарева подобрал как себе без обмана.","x":"Спосибо сработали отлично машина на 4 бала полностью оправдала ожидания.","m":"","th":["price"],"img":"","bo":0},{"d":"2024-08","a":"Ольга","t":"Огромное спасибо Сергею за мою красавицу,19 июля заказали машину из Японии, 14 августа получила ключи. Всё быстро, слаженно, без каких либо проблем.!","x":"Всё быстро, слаженно, без каких либо проблем.!","m":"","th":[],"img":"","bo":0},{"d":"2024-08","a":"Ната","t":"Первый раз решила купить б/п авто из Японии, обратилась в Автозаказ 28 и не пожалела. Сергей и Олег профессионалы своего дела, помогут определиться с выбором, проконсультируют по всем вопросам. Ведут на протяжении всей сделки от подписания договора до получения авто. Здесь всегда гостеприимство( кофе и чай), внимание к каждому клиенту, прозрачность сделки. Всем рекомендую!","x":"Первый раз решила купить б/п авто из Японии, обратилась в Автозаказ 28 и не пожалела.","m":"","th":["price","first"],"img":"","bo":0},{"d":"2024-07","a":"Иван","t":"Смотрел машины на Drom, приглянулся Honda Vezel. Решил позвонить продавцу, несмотря на позднее время. На мой звонок ответил Олег, все подробно и быстро рассказал. На следующий день решил поехать обсудить все нюансы доставки автомобиля с Японии. Олег и Сергей профессионально все объяснили, показали. Долго не думая, решил заказать автомобиль, быстро подписали договор и все оформили. Оставалось только дождаться привоза. На каждом этапе доставки автомобиля консультировали и отвечали на все вопросы. Через один месяц мы забрали свой автомобиль в красивом и единственном цвете в Благовещенске Графит- ). Все быстро, четко, открыто! Спасибо большое за порядочно проделанную работу! Очень приятно было получить.С вами было приятно работать!","x":"Долго не думая, решил заказать автомобиль, быстро подписали договор и все оформили.","m":"Honda Vezel","th":["touch","term"],"img":"","bo":0},{"d":"2024-07","a":"Демьян","t":"Спасибо за доставку автомобиля! Все мероприятия были выполнены быстро, слаженно, без нареканий, Сергей и Олег подробно объяснили все этапы доставки автомобиля. Быстрая доставка, честные люди! Обращайтесь и убедитесь сами!","x":"Все мероприятия были выполнены быстро, слаженно, без нареканий, Сергей и Олег подробно объяснили все этапы доставки автомобиля.","m":"","th":["term"],"img":"","bo":0},{"d":"2024-07","a":"Надежда","t":"Случайно обратились к ребятам, не по знакомству, но уже с первых минут общения было понятно, что с Сергеем можно иметь дело! Профессионально, четко, грамотно и главное быстро отработали наш запрос, консультировали на каждом этапе ( вплоть до постановки на учет) и уже через месяц мы забрали свое авто! Спасибо за оперативно проделанную работу, профессионализм и порядочность! Однозначно рекомендую компанию Автозаказ28","x":"Случайно обратились к ребятам, не по знакомству, но уже с первых минут общения было понятно, что с Сергеем можно иметь дело!","m":"","th":["term","docs"],"img":"","bo":0},{"d":"2024-07","a":"Сергей","t":"Очень быстро сработали ребята. Всего один месяц и машина у меня.","x":"Всего один месяц и машина у меня.","m":"","th":["term"],"img":"r142_0","bo":1},{"d":"2024-07","a":"Татьяна","t":"Огромное спасибо за машину, буду водить с удовольствием, приятно было сотрудничать. Рекомендую.","x":"Огромное спасибо за машину, буду водить с удовольствием, приятно было сотрудничать.","m":"","th":[],"img":"","bo":0},{"d":"2024-07","a":"Alina","t":"Хотелось бы оставить отзыв о работе с авто заказом 28, хотели приобрести достойный автомобиль по хорошей цене. Запросы были не низкие, пробег около 30, аукционный лист не ниже 4. В итоге дождались своего красавца, в идеальном состоянии, как новая. Сергей что работал с нами, всегда был на связи и очень трепетно относится к вопросам правильно ли мы все поняли, все чеки были пояснены. Сейчас много разных компаний, но в эту можно обращаться без сомнений!) очень была рада сотрудничеству","x":"Хотелось бы оставить отзыв о работе с авто заказом 28, хотели приобрести достойный автомобиль по хорошей цене.","m":"","th":["touch","report"],"img":"","bo":0},{"d":"2024-06","a":"Юрий","t":"Купил автомобиль в компании АВТОЗАКАЗ 28 тойота хариер 2021 года. Машина санкционная!\nАукционный бал 4,5 с небольшим пробегом!\nОчень рад что обратился в эту компанию!\nМашина по цене пришла на много НИЖЕ рыночной.\nМашина пришла можно сказать новая в идеальном состоянии! Ничего из автомобиля небыло изъято в процессе доставки до пункта назначения! На всем протяжении ребята держали в курсе передвижения, и выхода авто с таможни и выдачи документов! Практически все действия которые от них зависели делали оперативно! Что касается денежных вопросов все оговаривается в договоре и при платеже все прозрачно!\nОчень доволен автомобилем!\nХочу выразить слова благодарности коллективу этой компании!\nОчень рекомендую данную компанию!","x":"Что касается денежных вопросов все оговаривается в договоре и при платеже все прозрачно!","m":"Toyota Harrier","th":["price","touch","docs"],"img":"","bo":0},{"d":"2024-06","a":"Мария","t":"Хочу оставить свой отзыв) Сергей, спасибо вам огромное за проделанную работу. Вы с нами были на связи 24/7, отвечали на все наши вопросы, а у нас их было не мало, так как мы ни разу не заказывали машину с аукциона и нам было как то страшно, что вдруг что то не получится и деньги уйдут в никуда, но с вами было нам спокойно и легко. Машину заказали 30 марта и пришла она 1 мая- всего за месяц, это очень радует, что в такие короткие сроки вы доставляете нам машины. Спасибо вам большое. Обратимся к вам еще )","x":"Вы с нами были на связи 24/7, отвечали на все наши вопросы, а у нас их было не мало, так как мы ни разу не заказывали машину с аукциона и нам было как то страшно, что вдруг что то не…","m":"","th":["touch","term","first"],"img":"","bo":0},{"d":"2024-06","a":"Лариса","t":"Я, очень довольна приобретением машины у вашей компании. Процесс покупки и доставки прошел на высоком уровне. Машина пришла в отличном состоянии, как описано, полностью соответствовала моим ожиданиям. Огромное спасибо Сергею и его команде за профессионализм и качественный сервис.","x":"Я, очень довольна приобретением машины у вашей компании.","m":"","th":[],"img":"","bo":0},{"d":"2024-06","a":"Андрей","t":"Хочу сказать огромное спасибо Сергею! Очень приятно работать с такими людьми! Всё подробно рассказал, объяснил и самое главное, очень быстро доставили интересующий автомобиль! Машина чистенькая, целая. Всё просто супер!","x":"Всё подробно рассказал, объяснил и самое главное, очень быстро доставили интересующий автомобиль!","m":"","th":["term"],"img":"r148_0","bo":1},{"d":"2024-06","a":"Людмила","t":"Хочу выразить огромную благодарность за проделанную работу. Машина пришла за месяц. Очень довольна. Сергей всегда на связи, любой вопрос -сразу отвечает. Советую компанию Автозаказ 28!","x":"Сергей всегда на связи, любой вопрос -сразу отвечает.","m":"","th":["touch","term"],"img":"","bo":0},{"d":"2024-06","a":"Маргарита","t":"Всем добрый день! Хочу оставить отзыв о компании Автозаказ28. Теперь когда ожидание авто и трудности позади, могу сказать огромное спасибо за выполненую работу. Всё очень оперативно и доступно. Ребята работают по договору, на всех этапах дают информацию с фото отчётом, что очень радует.\nМоё авто пришло менее чем за два месяца!\nСергею и Олегу ещё раз огромное спасибо за выполненую работу, регулярную поддержку и консультацию. Успехов Вам и хороших продаж.","x":"Ребята работают по договору, на всех этапах дают информацию с фото отчётом, что очень радует.","m":"","th":["report"],"img":"","bo":0},{"d":"2024-06","a":"Игорь","t":"Скажу сразу огромное спасибо! Пришёл заказывать от друга, который тоже покупал машину у этой компании. Машина непростая санкционная, сразу предупредили что сложности вывоза в отличии от обычных машин и ожидание до 3 месяцев, несмотря на это, решился заказывать, торговали месяц, людям доверял. Машина пришла за 3,5 месяца. В таком цвете только хотел, мокрый асфальт, люк с панорамой! Покупка себя полностью оправдала! Машина пришла целая никаких косяков и тд нет. Буду только рекомендовать вас, и всем рекомендую покупать здесь, доверять можно. Процветания вам и вашему бизнесу. Спасибо!","x":"Машина непростая санкционная, сразу предупредили что сложности вывоза в отличии от обычных машин и ожидание до 3 месяцев, несмотря на это, решился заказывать, торговали месяц, людям доверял.","m":"","th":["friend"],"img":"r151_0","bo":1},{"d":"2024-05","a":"Михаил","t":"Спасибо компании, привезли машину за месяц. Отличный везель 2015 года! Довольны покупкой, везде помогали, объясняли и всегда на связи были. Процветания вашей компании и спасибо еще раз!","x":"Довольны покупкой, везде помогали, объясняли и всегда на связи были.","m":"Honda Vezel","th":["touch","term"],"img":"","bo":0},{"d":"2024-05","a":"Анатолий","t":"Понравилось абсолютно все. Спасибо Сергею за выполненную работу. Компании успехов..Обращайтесь не пожалеете. Анатолий 19. 05 2024г","x":"Компании успехов..Обращайтесь не пожалеете.","m":"","th":[],"img":"","bo":0},{"d":"2024-05","a":"Роман","t":"С момента как получили машину, ездим уже 1.5месяца, все четко, без нареканий. Машиной очень довольны. Спасибо Сергею.","x":"С момента как получили машину, ездим уже 1.5месяца, все четко, без нареканий.","m":"","th":[],"img":"","bo":0},{"d":"2024-05","a":"Татьяна","t":"Хочу оставить отзыв о компании \"Автозаказ28\" и поблагодарить ребят, за то что привезли мне клуссную машину! Долго не могла решиться с приобретением авто, то цена не устраивала, то технические характеристики и большой пробег. По итогу было принято решение взять машину без пробега по России, относительно новую...Обращаясь в компанию \"Автозаказ28\" по началу меня терзали сомнения. НО уже по итогу проделанной компанией работы, я понимаю что все переживания были зря. Уровень организации работы \"Автозаказ28\" превзошёл все ожидания! Компания работает по договору (поэтому все прозрачно, без обмана), в договоре указана конечная цена, которая не изменяется ни при каких обстоятельствах, будь то изменение курса валют, транспотировка и др. Все риски на себя берет компания. На всех этапах сделки Вам на телефон присылают фото и видео отчёт о том, что происходит с Вашей машиной. Сергей консультантирует Вас по всем интересующим вопросам 24/7, оказывает помощь при оплате платежей. По приходу в Благовещенск машину обязательно моют и вручают ее Вам в идеальном состоянии! Ребята, спасибо Вам огромнейшее!","x":"Компания работает по договору (поэтому все прозрачно, без обмана), в договоре указана конечная цена, которая не изменяется ни при каких обстоятельствах, будь то изменение курса валют…","m":"","th":["price","touch","report"],"img":"r155_0","bo":1},{"d":"2024-05","a":"Светлана","t":"Выражаю огромную благодарность компании и лично Сергею. Ответственно и качественно подошли к покупке автомобиля. В процессе поставки обо всех передвижениях информировали. С документами все в порядке. На все интересующие вопросы ответили. Приятно было сотрудничать","x":"Ответственно и качественно подошли к покупке автомобиля.","m":"","th":["report","docs"],"img":"","bo":0},{"d":"2024-04","a":"Олеся","t":"Хочу выразить огромную благодарность компании и в частности Сергею, за подбор и быструю доставку б/п машины из Японии. Машина прошла таможню и мы решили сами забрать её не ждать автовоз. Сергей дал адрес парковки где она стояла. В общем машиной довольны! Обращайтесь парни профессионалы своего дела.","x":"Машина прошла таможню и мы решили сами забрать её не ждать автовоз.","m":"","th":[],"img":"","bo":0},{"d":"2024-04","a":"Владислав","t":"Обратился к ребятам с просьбой покупки и доставки в Благовещенск редкого специфичного автомобиля. Сергей помог выбрать на аукционе, организовать логистику и не смотря на трудности вывоза данных машин из Японии теперь она у меня. Спасибо большое)","x":"Сергей помог выбрать на аукционе, организовать логистику и не смотря на трудности вывоза данных машин из Японии теперь она у меня.","m":"","th":[],"img":"r158_0","bo":1},{"d":"2024-04","a":"Надежда","t":"Ребята большие молодцы, профессионалы своего дела. Привезли машину быстро, меньше месяца. Огромное им СПАСИБО.","x":"Привезли машину быстро, меньше месяца.","m":"","th":["term"],"img":"","bo":0},{"d":"2024-04","a":"Дима","t":"Отличные ребята, большое Вам спасибо!","x":"Отличные ребята, большое Вам спасибо!","m":"","th":[],"img":"r160_0","bo":1},{"d":"2024-04","a":"Петр","t":"Хочу выразить благодарность, за честный и оперативный подбор и доставку автомобиля из Японии. Заказывал из Краснодара, авто пришло таким какое было на фото. Остался всем доволен и крайне рекомендую!","x":"Заказывал из Краснодара, авто пришло таким какое было на фото.","m":"","th":[],"img":"","bo":0},{"d":"2024-04","a":"Клиент","t":"Хочу выразить благодарность за работу. Через данную компанию мне привезли автомобиль с Японии.\nПо времени все прошло быстро, за месяц я стала обладателем нового автомобиля.\nСпасибо большое за оперативность и четкость.\nМашину отдали чистую-за это отдельное спасибо.","x":"По времени все прошло быстро, за месяц я стала обладателем нового автомобиля.","m":"","th":["term"],"img":"","bo":0},{"d":"2024-04","a":"Клиент","t":"Всё отлично, ребята молодцы.Рекомендую!","x":"Всё отлично, ребята молодцы.Рекомендую!","m":"","th":[],"img":"r163_0","bo":1},{"d":"2024-04","a":"Demid","t":"Был в поиске Toyota CH-R для супруги на вторичном рынке. Случайно наткнулся на объявление Сергея о продаже авто. Созвонились, минут 40 обсуждали нынешние условия покупки машины, все тонкости и трудности, и было принято решение привезти авто под себя с Японии.\nСергей на первый взгляд вызвал положительные эмоции и доверительное отношение само собой выстроилось. В дальнейшем отношения только улучшились.\nВ этот же день заключи договор о приобретении CH-R, со следующего дня начали торговать. Мы вместе выбирали и отсеивали варианты, Сергей очень оперативно и по делу выявлял плюсы и минусы того или иного лота.\nМашину купили за 5 дней! Очень бодрую, и в интересной комплектации! Ну а дальше началась бюрократия, посещения банков, которые Сергей курировал, подсказывал и объяснял как сделать лучше и быстрей. Полное сопровождение как информацией о машине и ее местонахождение, так и обо всех процедурах оплаты, согласований выгодного курса валют и т.д.\nПосле прохождения таможни и всех сопутствующих процедур, Сергей организовал доставку в г. Благовещенск и передачу авто в детейлинг для последующей оклейки авто.\nСпустя всего месяц после приобретения авто было у нас в семье! Я при этом особо ничего и не делал, всем процессом руководил Сергей!\nОчень отзывчивый, добрый, клиенториентированный человек. Все быстро, по факту и по делу! Спасибо за Вашу работу, теперь я всегда Ваш клиент! Жму руку","x":"В этот же день заключи договор о приобретении CH-R, со следующего дня начали торговать.","m":"Toyota C-HR","th":["term"],"img":"r164_0","bo":1},{"d":"2024-03","a":"Олеся","t":"Заказали авто в этой компании, очень благодарны и довольны. Работают по договору, всегда на связи. Сергею, особенно огромное спасибо, всегда ответит, разьяснит, все понятно и доступно. 1,5 месяца ожидания, и вот наш огненный Хонда Везель доставлен прям к подьезду. Все супер, чётко без обмана. Кому нужна машинка, обращайтесь только к ним, проверено! Все супер, ещё раз огромное спасибо!","x":"Работают по договору, всегда на связи.","m":"Honda Vezel","th":["price","touch"],"img":"","bo":0},{"d":"2024-03","a":"Клиент","t":"Заказывала авто в этой компании, довольна на все. Сергей помогает на всех этапах покупки, всегда на связи, объясняет всё доступно и понятно. Обращайтесь не пожелаете! Вы лучшие! За следующим авто только к вам","x":"Сергей помогает на всех этапах покупки, всегда на связи, объясняет всё доступно и понятно.","m":"","th":["touch"],"img":"","bo":0},{"d":"2024-03","a":"Людмила","t":"Приехали в данную компанию с целью обмена своего авто Nissan Tiida, на автомобиль с аукционов Японии, машину привезли, обмен состоялся, все честно, правильно как договаривались, машиной довольны яркий, красивый Vezel! Спасибо за работу и процветания вашему бизнесу!","x":"Приехали в данную компанию с целью обмена своего авто Nissan Tiida, на автомобиль с аукционов Японии, машину привезли, обмен состоялся, все честно, правильно как договаривались, машиной…","m":"Honda Vezel","th":["price","trade"],"img":"","bo":0},{"d":"2024-03","a":"Захар","t":"Заказал Хонда везел через данную компанию. Работой компании доволен: помогли определиться с выбором, подобрали авто под нужный бюджет, быстро доставили. При этом, ответили на все интересующие вопросы и были на связи 24/7. Спасибо!","x":"При этом, ответили на все интересующие вопросы и были на связи 24/7.","m":"Honda Vezel","th":["touch","term"],"img":"","bo":0},{"d":"2024-03","a":"Наталья","t":"Сергей знаток своего дела! Заказали машину, пришла через 3 недели которые пролетели не заметно! Услугой остались довольны! Машиной тоже очень довольны!","x":"Заказали машину, пришла через 3 недели которые пролетели не заметно!","m":"","th":["term"],"img":"r169_0","bo":1},{"d":"2024-03","a":"Юрий","t":"Сергей молодец знает своё дело. Заказали Хонда Фрид+ 2019 года. Быстро нашли и купили на аукционе в Японии. Ровно месяц и пришла. Рекомендуем молодец.","x":"Быстро нашли и купили на аукционе в Японии.","m":"Honda Freed","th":["term"],"img":"","bo":0},{"d":"2024-03","a":"Валерий","t":"Заказал Тойота-Виш, машину привезли меньше, чем месяц, всё понравилось, не каких лишних сборов, всё как договаривались, машина просто огонь. Большое спасибо.","x":"Заказал Тойота-Виш, машину привезли меньше, чем месяц, всё понравилось, не каких лишних сборов, всё как договаривались, машина просто огонь.","m":"Toyota Wish","th":["price","term"],"img":"","bo":0},{"d":"2024-03","a":"Алёна","t":"Хочу выразить огромную благодарность Сергею, все прошло на высшем уровне! Машиной довольны, все соответствует действительности и оправдывает своих ожиданий) Спасибо что были всегда на связи, на все вопросы были даны подробные ответы) Всем рекомендуем обращаться за машиной именно сюда!","x":"Машиной довольны, все соответствует действительности и оправдывает своих ожиданий) Спасибо что были всегда на связи, на все вопросы были даны подробные ответы) Всем рекомендуем…","m":"","th":["touch"],"img":"","bo":0},{"d":"2024-03","a":"Любовь","t":"Заказали машину, пришла за месяц, весь процесс от сбора документов до оформления авто все сделали быстро, очень довольна покупкой! Все очень позитивно, сервис отличный! Следующую машину покупать только здесь буду!","x":"Заказали машину, пришла за месяц, весь процесс от сбора документов до оформления авто все сделали быстро, очень довольна покупкой!","m":"","th":["term","docs"],"img":"r173_0","bo":1},{"d":"2024-02","a":"Ольга","t":"Обратилась в эту компанию для заказа автомобиля. Все было сделано по высшему уровню. Чистая, прозрачная сделка. Подбор по бюджету и пожеланиям. Буду обращаться ещё однозначно.","x":"Чистая, прозрачная сделка.","m":"","th":["price"],"img":"r174_0","bo":1},{"d":"2024-02","a":"Светлана","t":"Все отлично. Хочу сказать огромное спасибо Сергею и его команде. Сопровождение и помощь на каждом этапе на высшем уровне! Авто пришло быстро, превзошло все ожидания, чистая прозрачная сделка. Рекомендую при покупке, обращаться только к ним. Грамотные специалисты, знающие свое дело. Ещё раз огромное спасибо, процветания вам!: )","x":"Авто пришло быстро, превзошло все ожидания, чистая прозрачная сделка.","m":"","th":["price"],"img":"r175_0","bo":1},{"d":"2024-02","a":"Виктория","t":"Грамотный подход к сделке, все чисто, прозрачно и честно, машину привезли очень быстро, в отличном состоянии, соответствует аукционнику. Было приятно работработать. Рекомендуем на все 100%","x":"Грамотный подход к сделке, все чисто, прозрачно и честно, машину привезли очень быстро, в отличном состоянии, соответствует аукционнику.","m":"","th":[],"img":"","bo":0},{"d":"2024-02","a":"Дима","t":"Отлично работаете! Купил Honda Vezel RS! Машина пришла быстро за 3 недели! Цвет красивый, состояние новой машины, большое спасибо!","x":"Машина пришла быстро за 3 недели!","m":"Honda Vezel","th":["term"],"img":"","bo":0},{"d":"2024-01","a":"Анастасия","t":"Сказать, что я в восторге-это ничего не сказать! Такого вредного и придирчивого Клиента, как я, еще нужно поискать! Очень благодарна Сергею за мою красотку! Сергей-мастер своего дела! Всё сделал на высшем уровне! От первой консультации до передачи автомобиля! Я безумно счаслива, что выбрала именно эту компанию. Огромное спасибо! Процветания Вам и только благодарных Клиентов!","x":"От первой консультации до передачи автомобиля!","m":"","th":[],"img":"","bo":0},{"d":"2024-01","a":"Анюта","t":"Сергей, огромное Вам спасибо за мою машинку! Пришла очень быстро. Состояние автомобиля просто огонь! Ваша работа с покупателем на высшем уровне! Всегда на связи, развёрнутый ответ на все вопросы, прозрачность сделки. По приходу авто помощь по всем вопросам...от замены антифриза, покупки и переобувки колёс до помощи в оформлении автомобиля! Безумно Вам благодарна! Всем советую, обращайтесь! За новым авто только к Вам!","x":"Всегда на связи, развёрнутый ответ на все вопросы, прозрачность сделки.","m":"","th":["price","touch","term","docs"],"img":"","bo":0},{"d":"2024-01","a":"Алексей","t":"Ребята работают отлично!\nКак договорились, все пришло вовремя и не каких лишних комиссий! Спасибо, следующий заказ размещу опять у Вас","x":"Как договорились, все пришло вовремя и не каких лишних комиссий!","m":"","th":["price"],"img":"","bo":0},{"d":"2024-01","a":"Анастасия","t":"Отзыв, полный благодарности! Заказали автомобиль в декабре, пришёл меньше, чем за месяц. Сергей помог определиться с оптимальным выбором в рамках бюджета, учитывая все пожелания. Дал компетентные рекомендации, сориентировал по всем юридическим вопросам и просто по- человечески дал хорошие советы. Платежи прозрачны, понятно, сколько и за что конкретно платишь. Автомобиль в отличном состоянии, как по косметике, так и по технической части Сергей на связи на всех этапах сделки, и даже после передачи автомобиля обращалась с некоторыми вопросами, помог во всём! Заказал резину, сам переобул и помыл машину, заменил антифриз. Большое спасибо не только за профессионализм, но и за человечность и приятный сервис. За следующей машиной только сюда","x":"Заказали автомобиль в декабре, пришёл меньше, чем за месяц.","m":"","th":["price","touch","term"],"img":"r181_0","bo":1},{"d":"2023-12","a":"Светик","t":"Воспользовались услугами Автозаказ28 в ноябре 2023 и очень рады! Честные, отзывчивые, понимающие, терпеливые продавцы! Все чётко и честно! Все подскажут и сделают наилучшим образом учитывая интересы покупателя. Спасибо им ОГРОМНОЕ! Процветания бизнесу и много благодарных клиентов!","x":"Воспользовались услугами Автозаказ28 в ноябре 2023 и очень рады!","m":"","th":[],"img":"r182_0","bo":1},{"d":"2023-12","a":"Клиент","t":"Пришёл Красавчик, отличный автомобиль! Рекомендую данную фирму! Надежно, все платежи прозрачны, быстро. Спасибо!","x":"Надежно, все платежи прозрачны, быстро.","m":"","th":["price"],"img":"","bo":0}];
